/**
 * Race HUD — WaveKill instrument language on the WaveSpace canvas.
 *
 * Layout (same clusters as WaveKill):
 *   · top-left info slab — place, lap (seg), race clock (seg), LAST/BEST
 *   · bottom-right speed plate — SPEED / KM/H + large seven-seg readout
 *   · top-right COURSE minimap + standings ladder
 *   · Screens compositions for countdown / GO / lap / results
 */

import { CONFIG } from '../core/config';
import { clamp, clamp01, formatTime, ordinal } from '../core/mathx';
import { HEX } from '../core/palette';
import type { GameContext, Racer } from '../core/types';
import {
  FONT_STACK,
  PLATE_SKEW,
  PLATE_W,
  cutPath,
  inkText,
  inked,
  plate,
  rgba,
  segText,
  segWidth,
  slantPath,
} from './inkDraw';
import { drawNitroHud } from '../nitro';
import { createLockHudAnim, drawLockHud, tickLockHudAnim, type LockHudAnim } from './lockHud';
import { Minimap } from './minimap';
import { Screens } from './screens';
import { drawShipDamageMap } from './shipMap';

export class RaceHud {
  /** When true, lift instruments above on-screen pads and soften keyboard hints. */
  touchUi = false;
  private pulse = 0;
  private placeFlash = 0;
  private placeDir = 0;
  private lastPlace = 1;
  private shownKmh = 0;
  private readonly screens = new Screens();
  private readonly lockAnim: LockHudAnim = createLockHudAnim();
  private minimap: Minimap | null = null;
  private mapLaidOut = false;
  private lastMapKey = '';
  private inset = { top: 20, right: 24, bottom: 24, left: 22 };

  /** Clearance for notches + on-screen touch pads. */
  private layoutInset(cssW: number, cssH: number) {
    const narrow = cssW < 820 || this.touchUi;
    return {
      top: this.touchUi ? 18 : 20,
      right: this.touchUi ? 14 : 24,
      // Leave room for steer (left) / action cluster (right) on mobile.
      bottom: this.touchUi ? Math.min(210, cssH * 0.34) : 24,
      left: this.touchUi ? 14 : 22,
      narrow,
    };
  }

  draw(g: CanvasRenderingContext2D, cssW: number, cssH: number, ctx: GameContext) {
    const inset = this.layoutInset(cssW, cssH);
    this.inset = inset;
    const s = Math.min(Math.max(cssH / 810, this.touchUi ? 0.8 : 0.72), 1.35);
    if (!this.minimap) this.minimap = new Minimap(ctx.track);
    const map = (this.touchUi ? 124 : 148) * s;
    const mapKey = `${Math.round(cssW)}x${Math.round(cssH)}:${Math.round(map)}:t${this.touchUi ? 1 : 0}`;
    if (!this.mapLaidOut || mapKey !== this.lastMapKey) {
      this.minimap.layout(cssW - inset.right - map, inset.top, map);
      this.mapLaidOut = true;
      this.lastMapKey = mapKey;
    }
    const p = ctx.player;
    const dt = ctx.dt;
    this.pulse += dt;

    if (p.place !== this.lastPlace) {
      this.placeDir = this.lastPlace - p.place; // + = gained places
      this.placeFlash = 1;
      this.lastPlace = p.place;
    }
    this.placeFlash = Math.max(0, this.placeFlash - dt * 1.8);

    const targetKmh = Math.abs(p.state.forwardSpeed) * 3.6;
    this.shownKmh += (targetKmh - this.shownKmh) * Math.min(1, dt * 14);

    this.screens.update(ctx, dt);

    // Hide dense instruments under results board (WaveKill does the same).
    const showInstruments = ctx.phase !== 'results';

    if (showInstruments) {
      this.drawInfoSlab(g, ctx, cssW, cssH, s);
      this.drawSpeed(g, ctx, cssW, cssH, s);
      this.minimap!.drawChrome(g, s);
      this.minimap!.drawLive(g, ctx, s, this.pulse);
      this.drawStandings(g, ctx, cssW, cssH, s);
      this.drawCameraChip(g, ctx, s);
      this.drawLoadoutRack(g, ctx, cssW, cssH, s);
      if (ctx.combat && ctx.phase === 'racing' && ctx.combatHud) {
        this.drawCombatLock(g, ctx, cssW, cssH, s);
      }
      if (p.state.nitroTime > 0) {
        this.drawNitroFrame(g, cssW, cssH, s);
      }
      if (ctx.impactHud && ctx.impactHud.flash > 0) {
        this.drawImpactFlash(g, ctx, cssW, cssH, s);
      }
      if (ctx.pickupHud && ctx.pickupHud.flash > 0) {
        this.drawPickupToast(g, ctx, cssW, cssH, s);
      }
      if (p.destroyed && ctx.phase === 'racing') this.drawWrecked(g, cssW, cssH, s);
      else if (p.wrongWay && ctx.phase === 'racing') this.drawWrongWay(g, cssW, cssH, s);
    }

    // Presentation compositions own the centre of the frame.
    if (ctx.phase === 'countdown') this.screens.countdown(g, ctx, cssW, cssH, s);
    this.screens.go(g, ctx, cssW, cssH, s);
    if (ctx.phase === 'racing') this.screens.lapFlash(g, ctx, cssW, cssH, s);
    if (ctx.phase === 'finished') this.screens.finishFlash(g, ctx, cssW, cssH, s);
    if (ctx.phase === 'results') this.screens.results(g, ctx, cssW, cssH, s);
  }

  /** CSS-pixel hit for the results "Race Again" plate. */
  hitRestart(cssX: number, cssY: number): boolean {
    const b = this.screens.restartBtn;
    if (!b) return false;
    return cssX >= b.x && cssX <= b.x + b.w && cssY >= b.y && cssY <= b.y + b.h;
  }

  setRestartHover(cssX: number, cssY: number) {
    this.screens.restartHover = this.hitRestart(cssX, cssY);
  }

  clearRestartHover() {
    this.screens.restartHover = false;
  }

  reset() {
    this.screens.resetLatches();
    this.placeFlash = 0;
    this.lastPlace = 1;
    this.shownKmh = 0;
    Object.assign(this.lockAnim, createLockHudAnim());
  }

  private drawCombatLock(
    g: CanvasRenderingContext2D,
    ctx: GameContext,
    cssW: number,
    cssH: number,
    s: number,
  ) {
    const h = ctx.combatHud!;
    let lockX: number | null = null;
    let lockY: number | null = null;
    if (h.lockScreenX != null && h.lockScreenY != null) {
      lockX = (h.lockScreenX * 0.5 + 0.5) * cssW;
      lockY = (-h.lockScreenY * 0.5 + 0.5) * cssH;
    }
    const inp = {
      w: cssW,
      h: cssH,
      s,
      time: ctx.time,
      lockName: h.lockName,
      lockStrength: h.lockStrength,
      lockHitChance: h.lockHitChance,
      lockX,
      lockY,
      incoming: h.incoming,
      breakMeter: h.breakMeter,
      breakFlash: h.breakFlash,
      lockImmune: h.lockImmune,
      canFire:
        !!h.weaponReady &&
        !!h.lockName &&
        h.lockStrength >= 0.12 &&
        (h.rocketCd ?? 0) <= 0,
      holdPending: h.holdFirePending,
      lockHp: h.lockHp,
      lockMaxHp: h.lockMaxHp,
    };
    tickLockHudAnim(this.lockAnim, inp, ctx.dt);
    drawLockHud(g, this.lockAnim, inp);
  }

  /**
   * WaveKill assault rack — hull map + integrity + rockets + nitro.
   */
  private drawLoadoutRack(
    g: CanvasRenderingContext2D,
    ctx: GameContext,
    cssW: number,
    cssH: number,
    s: number,
  ) {
    const combat = ctx.combat;
    const nitro = ctx.nitro;
    const showHull = ctx.phase === 'racing' || ctx.phase === 'countdown';
    // Show rocket rack through countdown so ammo is obvious before green.
    if (!combat && !nitro && !showHull) return;

    // Left column — WaveKill assault rack anchor (keeps centre clear for racing).
    const colW = 220 * s;
    const bx = this.inset.left;
    const by = cssH - this.inset.bottom;
    const hullBlock = showHull ? 128 : 0;
    const combatBlock = combat ? 44 : 0;
    const nitroBlock = nitro ? 50 : 0;
    let y = by - (hullBlock + combatBlock + nitroBlock) * s;

    if (showHull) {
      const h = ctx.player.hull;
      const st = ctx.player.state;
      const map = drawShipDamageMap(g, bx, y, s, {
        zones: h.zones,
        lastHitZone: h.lastHitZone,
        lastHitFlash: h.lastHitFlash,
        hp: h.hp,
        maxHp: h.maxHp,
        time: this.pulse,
      });

      const hx = bx + map.w + 10 * s;
      const hw = colW - map.w - 10 * s;
      const hh = 42 * s;
      const hy = y + 8 * s;
      const hpFrac = clamp01(h.hp / Math.max(1, h.maxHp));
      const flash = h.hitFlash > 0 || st.hitFlash > 0;
      const hullPath = slantPath(hx, hy, hw, hh, hh * PLATE_SKEW);
      plate(g, hullPath, s, { hatchRect: [hx, hy, hw, hh] });
      inkText(g, 'INTEGRITY', hx + 12 * s, hy + 15 * s, {
        font: `800 ${Math.round(10 * s)}px ${FONT_STACK}`,
        fill: rgba(flash ? HEX.warn : HEX.hudDim, 1),
        tracking: 1.8 * s,
      });
      inkText(g, `${Math.round(h.hp)}`, hx + hw - 12 * s, hy + 15 * s, {
        font: `800 ${Math.round(12 * s)}px ${FONT_STACK}`,
        fill: rgba(HEX.hudPaper, 1),
        align: 'right',
        tracking: 1.2 * s,
      });
      const barX = hx + 12 * s;
      const barY = hy + 24 * s;
      const barW = hw - 24 * s;
      const barH = 10 * s;
      g.fillStyle = rgba(HEX.hudInk, 1);
      g.fillRect(barX, barY, barW, barH);
      g.fillStyle = rgba(hpFrac > 0.35 ? HEX.raceLine : HEX.warn, 1);
      g.fillRect(barX, barY, barW * hpFrac, barH);
      g.strokeStyle = rgba(HEX.hudPaper, 0.85);
      g.lineWidth = 1.4 * s;
      g.strokeRect(barX, barY, barW, barH);

      if (h.lastHitZone && h.lastHitFlash > 0) {
        inkText(g, `HIT ${h.lastHitZone.toUpperCase()}`, hx + 12 * s, hy - 4 * s, {
          font: `800 ${Math.round(10 * s)}px ${FONT_STACK}`,
          fill: rgba(HEX.warn, 0.55 + h.lastHitFlash),
          tracking: 1.6 * s,
        });
      }

      y += map.h + 10 * s;
    }

    if (combat) {
      const st = ctx.player.state;
      const hud = ctx.combatHud;
      const ammo = hud?.ammo ?? (st.weapon === 'missile' ? st.weaponAmmo : 0);
      const max = hud?.maxAmmo ?? 1;
      y = this.drawAmmoRow(
        g,
        bx,
        y,
        colW,
        s,
        hud?.weaponReady
          ? 'ROCKET · FIRE'
          : hud?.holdFirePending
            ? 'ROCKET · HOLD…'
            : hud && hud.lockStrength > 0.08
              ? 'ROCKET · LOCKING'
              : this.touchUi
                ? 'ROCKET · FIRE'
                : 'ROCKET · F',
        ammo,
        max,
        HEX.warn,
        hud?.rocketCd ?? 0,
        hud?.rocketCdMax ?? 1.25,
      );
      y += 8 * s;
    }

    if (nitro) {
      drawNitroHud(
        g,
        { x: bx, y, w: colW, h: 42 * s, scale: s, label: this.touchUi ? 'NITRO' : 'NITRO · N' },
        nitro,
      );
    }
  }

  /** One ammo / charge row with cooldown wash. Returns y below the row. */
  private drawAmmoRow(
    g: CanvasRenderingContext2D,
    x: number,
    y: number,
    colW: number,
    s: number,
    label: string,
    count: number,
    max: number,
    litHex: number,
    cd: number,
    cdMax: number,
  ): number {
    const rowH = 36 * s;
    const plateP = slantPath(x, y, colW, rowH, rowH * PLATE_SKEW);
    plate(g, plateP, s, { hatchRect: [x, y, colW, rowH] });

    inkText(g, label, x + 12 * s, y + 14 * s, {
      font: `800 ${Math.round(10 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.hudPaper, 1),
      tracking: 1.5 * s,
    });

    const cellW = 16 * s;
    const cellH = 12 * s;
    const gap = 5 * s;
    const cellsW = max * (cellW + gap) - gap;
    let cx = x + colW - 12 * s - cellsW;
    const cy = y + rowH * 0.5 - cellH * 0.5;
    for (let i = 0; i < max; i++) {
      const lit = i < count;
      const cell = slantPath(cx, cy, cellW, cellH, cellH * PLATE_SKEW);
      inked(
        g,
        cell,
        rgba(lit ? litHex : HEX.hudInk, 1),
        rgba(HEX.hudPaper, lit ? 1 : 0.4),
        PLATE_W * s,
      );
      cx += cellW + gap;
    }

    if (cdMax > 0 && cd > 0) {
      const frac = clamp01(cd / cdMax);
      const bx = x + 12 * s;
      const by = y + rowH - 8 * s;
      const bw = colW - 24 * s;
      g.fillStyle = rgba(HEX.hudInk, 0.95);
      g.fillRect(bx, by, bw, 4 * s);
      g.fillStyle = rgba(HEX.hudDim, 1);
      g.fillRect(bx, by, bw * (1 - frac), 4 * s);
      g.fillStyle = rgba(HEX.warn, 0.85);
      g.fillRect(bx + bw * (1 - frac), by, bw * frac, 4 * s);
    }

    return y + rowH;
  }

  // ── Top-left: place · lap · clock · splits ─────────────────────────────────

  private drawInfoSlab(
    g: CanvasRenderingContext2D,
    ctx: GameContext,
    _w: number,
    _h: number,
    s: number,
  ) {
    const ix = this.inset.left;
    const iy = this.inset.top;
    const iw = 292 * s;
    const ih1 = 92 * s;
    const ih = 138 * s;
    const p = ctx.player;

    const slab = slantPath(ix, iy, iw, ih, ih * PLATE_SKEW);
    plate(g, slab, s, { hatchRect: [ix, iy, iw, ih] });

    const lead = p.place === 1;
    const dx = ix + 124 * s;
    g.strokeStyle = rgba(HEX.hudPaper, 0.4);
    g.lineWidth = 2 * s;
    g.beginPath();
    g.moveTo(dx + 20 * s, iy + 8 * s);
    g.lineTo(dx - 2 * s, iy + ih1 - 6 * s);
    g.stroke();
    const y2 = iy + ih1;
    g.beginPath();
    g.moveTo(ix + (ih - ih1) * PLATE_SKEW + 8 * s, y2);
    g.lineTo(ix + iw - 8 * s, y2);
    g.stroke();

    const flash = this.placeFlash;
    const pop = 1 + flash * flash * 0.16;
    const num = String(p.place);
    const suf = ordinal(p.place).slice(String(p.place).length).toUpperCase();
    g.save();
    g.translate(ix + 66 * s, iy + ih1 * 0.5);
    g.scale(pop, pop);
    const flashCol =
      flash > 0
        ? this.placeDir > 0
          ? rgba(HEX.raceLine, 1)
          : rgba(HEX.warn, 1)
        : lead
          ? rgba(HEX.boostHot, 1)
          : rgba(HEX.hudPaper, 1);
    inkText(g, num, -6 * s, 25 * s, {
      font: `900 ${Math.round(70 * s)}px ${FONT_STACK}`,
      fill: flashCol,
      ink: rgba(HEX.ink, 1),
      inkWidth: 6.5 * s,
      align: 'center',
      skew: 0.17,
    });
    inkText(g, suf, 24 * s, -8 * s, {
      font: `800 ${Math.round(22 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.hudDim, 1),
      align: 'left',
      skew: 0.17,
    });
    g.restore();

    if (flash > 0 && this.placeDir !== 0) {
      const up = this.placeDir > 0;
      const rise = (1 - flash) * 26 * s;
      g.save();
      g.globalAlpha = flash;
      g.translate(ix + 108 * s, iy + ih1 * 0.5 - (up ? rise : -rise));
      const arr = new Path2D();
      const d = up ? -1 : 1;
      arr.moveTo(0, 11 * s * d);
      arr.lineTo(9 * s, -3 * s * d);
      arr.lineTo(3.4 * s, -3 * s * d);
      arr.lineTo(3.4 * s, -12 * s * d);
      arr.lineTo(-3.4 * s, -12 * s * d);
      arr.lineTo(-3.4 * s, -3 * s * d);
      arr.lineTo(-9 * s, -3 * s * d);
      arr.closePath();
      inked(g, arr, up ? rgba(HEX.raceLine, 1) : rgba(HEX.warn, 1), rgba(HEX.ink, 1), 2 * s);
      g.restore();
    }

    const lx = ix + 150 * s;
    inkText(g, 'LAP', lx, iy + 26 * s, {
      font: `800 ${Math.round(12 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.hudDim, 1),
      align: 'left',
      tracking: 3.4 * s,
    });
    const lapNum = String(Math.min(p.lap + 1, CONFIG.race.laps));
    segText(g, `${lapNum}/${CONFIG.race.laps}`, lx, iy + 32 * s, 30 * s, {
      lit: rgba(HEX.hudPaper, 1),
      ink: rgba(HEX.ink, 1),
      inkWidth: 1.2 * s,
      align: 'left',
      skew: 0.1,
    });

    const t = Math.max(0, ctx.raceTime);
    segText(g, formatTime(t), lx, iy + 66 * s, 19 * s, {
      lit: rgba(HEX.waterCrest, 1),
      align: 'left',
      skew: 0.1,
    });

    const sy = y2 + 12 * s;
    const last = p.lapTimes.length ? p.lapTimes[p.lapTimes.length - 1] : NaN;
    const bestIsNew =
      p.lapTimes.length > 0 && isFinite(p.bestLap) && Math.abs(p.bestLap - last) < 1e-6;
    const cols: [string, number, string][] = [
      ['LAST', last, rgba(HEX.hudPaper, 1)],
      ['BEST', p.bestLap, bestIsNew ? rgba(HEX.raceLine, 1) : rgba(HEX.foamShade, 1)],
    ];
    cols.forEach(([label, value, col], i) => {
      const cx = ix + 20 * s + i * (iw - 44 * s) * 0.5;
      inkText(g, label, cx, sy + 22 * s, {
        font: `800 ${Math.round(11 * s)}px ${FONT_STACK}`,
        fill: rgba(HEX.hudDim, 1),
        align: 'left',
        tracking: 2.2 * s,
      });
      const has = isFinite(value) && value > 0;
      const tx = cx + 40 * s;
      if (has) {
        segText(g, formatTime(value), tx, sy + 6 * s, 17 * s, {
          lit: col,
          ink: rgba(HEX.ink, 1),
          inkWidth: 1.2 * s,
          align: 'left',
          skew: 0.1,
        });
      } else {
        g.strokeStyle = rgba(HEX.hudDim, 0.9);
        g.lineWidth = 3 * s;
        const dw = segWidth('0:00.000', 17 * s);
        for (let k = 0; k < 3; k++) {
          const x0 = tx + 4 * s + k * dw * 0.33;
          g.beginPath();
          g.moveTo(x0, sy + 14 * s);
          g.lineTo(x0 + dw * 0.2, sy + 14 * s);
          g.stroke();
        }
      }
    });
  }

  // ── Bottom-right: speed plate ──────────────────────────────────────────────

  private drawSpeed(
    g: CanvasRenderingContext2D,
    ctx: GameContext,
    cssW: number,
    cssH: number,
    s: number,
  ) {
    const rw = 210 * s;
    const rh = 88 * s;
    const rx = cssW - rw - this.inset.right;
    const ry = cssH - rh - this.inset.bottom;
    const boosting = ctx.player.state.boosting;

    plate(g, slantPath(rx, ry, rw, rh, rh * PLATE_SKEW), s, { hatchRect: [rx, ry, rw, rh] });
    inkText(g, 'SPEED', rx + 18 * s, ry + 21 * s, {
      font: `800 ${Math.round(11 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.hudDim, 1),
      tracking: 3 * s,
    });
    inkText(g, 'KM/H', rx + rw - 14 * s, ry + 21 * s, {
      font: `800 ${Math.round(11 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.hudDim, 1),
      align: 'right',
      tracking: 2.4 * s,
    });

    const val = Math.round(clamp(this.shownKmh, 0, 999));
    segText(g, String(val).padStart(3, '0'), rx + rw - 16 * s, ry + 33 * s, 44 * s, {
      lit: boosting ? rgba(HEX.boostHot, 1) : rgba(HEX.hudPaper, 1),
      ink: rgba(HEX.ink, 1),
      inkWidth: 2.6 * s,
      align: 'right',
      skew: 0.1,
    });

    const st = ctx.player.state;
    let tag: string | null = null;
    let tagCol: number = HEX.waterCrest;
    if (st.airborne) {
      tag = 'AIR';
      tagCol = HEX.waterCrest;
    } else if (st.forwardSpeed < -0.6) {
      tag = 'REV';
      tagCol = HEX.warn;
    }
    if (tag) {
      const tw = 62 * s;
      const tp = cutPath(rx + 14 * s, ry + rh - 28 * s, tw, 20 * s, 6 * s, 0b0101);
      plate(g, tp, s, { edge: rgba(tagCol, 0.95) });
      inkText(g, tag, rx + 14 * s + tw * 0.5, ry + rh - 12 * s, {
        font: `800 ${Math.round(12 * s)}px ${FONT_STACK}`,
        fill: rgba(tagCol, 1),
        align: 'center',
        tracking: 2.4 * s,
      });
    }
  }

  // ── Nitro screen shade (vignette + speed bars while nitro is lit) ───────────

  private drawNitroFrame(g: CanvasRenderingContext2D, w: number, h: number, s: number) {
    const k = 0.82 + 0.18 * Math.sin(this.pulse * 22);
    g.save();

    // Magenta/cyan radial shade — darkens the rim so the burn reads as tunnel vision.
    const cx = w * 0.5;
    const cy = h * 0.5;
    const vig = g.createRadialGradient(cx, cy, h * 0.18, cx, cy, h * 0.78);
    vig.addColorStop(0, 'rgba(0,0,0,0)');
    vig.addColorStop(0.45, rgba(HEX.boost, 0.04 * k));
    vig.addColorStop(0.72, rgba(HEX.boost, 0.22 * k));
    vig.addColorStop(1, rgba(HEX.ink, 0.55 * k));
    g.fillStyle = vig;
    g.fillRect(0, 0, w, h);

    // Soft full-frame wash
    g.fillStyle = rgba(HEX.boostHot, 0.06 * k);
    g.fillRect(0, 0, w, h);

    // Edge rails
    g.fillStyle = rgba(HEX.boost, 0.92 * k);
    g.fillRect(0, 0, w, 4 * s);
    g.fillRect(0, h - 4 * s, w, 4 * s);

    // Speed chevrons — denser / hotter than the old raceLine bars.
    for (const side of [0, 1]) {
      const X = side * w;
      const d = side ? -1 : 1;
      for (let i = 0; i < 8; i++) {
        const n = ((i * 7 + side * 3) % 5) / 4;
        const y = h * (0.06 + i * 0.11) + side * h * 0.04;
        const len = 90 * s + n * 180 * s;
        const th = (6 + ((i + side) % 3) * 3.6) * s;
        const bar = new Path2D();
        bar.moveTo(X, y);
        bar.lineTo(X + d * len, y + th * 0.45);
        bar.lineTo(X + d * len, y + th * 0.9);
        bar.lineTo(X, y + th * 1.5);
        bar.closePath();
        g.fillStyle = rgba(i % 2 === 0 ? HEX.boostHot : HEX.boost, (0.78 + 0.22 * n) * k);
        g.fill(bar);
      }
    }

    // Centre speed streaks — short dashes that crawl with pulse.
    g.strokeStyle = rgba(HEX.boostHot, 0.28 * k);
    g.lineWidth = 2 * s;
    for (let i = 0; i < 10; i++) {
      const a = ((i * 0.618 + this.pulse * 0.35) % 1) * Math.PI * 2;
      const r0 = h * (0.12 + (i % 4) * 0.04);
      const r1 = r0 + h * (0.08 + (i % 3) * 0.03);
      g.beginPath();
      g.moveTo(cx + Math.cos(a) * r0, cy + Math.sin(a) * r0);
      g.lineTo(cx + Math.cos(a) * r1, cy + Math.sin(a) * r1);
      g.stroke();
    }

    g.restore();
  }

  // ── Top-right standings ladder ─────────────────────────────────────────────

  private drawStandings(
    g: CanvasRenderingContext2D,
    ctx: GameContext,
    _cssW: number,
    _h: number,
    s: number,
  ) {
    const board = ctx.racers
      .filter((r) => !r.destroyed && r.state.hp > 0)
      .sort((a, b) => a.place - b.place);
    if (board.length === 0) return;
    const rowH = 24 * s;
    const gap = 4 * s;
    const map = this.minimap!;
    const w = map.size;
    const x = map.x;
    const y0 = map.y + map.size + 14 * s;
    const leader = board[0];

    for (let i = 0; i < board.length; i++) {
      const r = board[i];
      const y = y0 + i * (rowH + gap);
      const hex = [
        HEX.hull0,
        HEX.hull1,
        HEX.hull2,
        HEX.hull3,
        HEX.hull4,
        HEX.hull5,
        HEX.hull6,
        HEX.hull7,
      ][r.id % 8];
      const isPlayer = r.isPlayer;
      const rx = x + i * 6 * s;
      const plateW = w - i * 6 * s;
      const row = slantPath(rx, y, plateW, rowH, rowH * PLATE_SKEW);
      plate(g, row, s, {
        fill: rgba(isPlayer ? HEX.hudInk : HEX.inkSoft, 1),
        edge: rgba(HEX.hudPaper, isPlayer ? 0.95 : 0.7),
      });

      const chip = slantPath(rx + 4 * s, y + 3.5 * s, 7 * s, rowH - 7 * s, (rowH - 7 * s) * PLATE_SKEW);
      inked(g, chip, rgba(hex, 1), rgba(HEX.ink, 1), 1.6 * s);

      inkText(g, String(i + 1), rx + 23 * s, y + rowH - 7 * s, {
        font: `900 ${Math.round(17 * s)}px ${FONT_STACK}`,
        fill: rgba(i === 0 ? HEX.boostHot : HEX.hudPaper, 0.98),
        align: 'center',
        skew: 0.16,
      });

      inkText(g, r.destroyed ? 'DNF' : r.name.toUpperCase(), rx + 37 * s, y + rowH - 7 * s, {
        font: `800 ${Math.round(12 * s)}px ${FONT_STACK}`,
        fill: rgba(r.destroyed ? HEX.warn : isPlayer ? HEX.hudPaper : HEX.foamShade, 0.95),
        align: 'left',
        skew: 0.1,
        tracking: 1.1 * s,
      });

      const gapTxt = r.destroyed ? 'WRECK' : this.gapText(ctx, r, leader);
      inkText(g, gapTxt, rx + plateW - 9 * s, y + rowH - 7 * s, {
        font: `800 ${Math.round(11.5 * s)}px ${FONT_STACK}`,
        fill:
          gapTxt === 'LEAD'
            ? rgba(HEX.boostHot, 1)
            : gapTxt === 'WRECK' || isPlayer
              ? rgba(HEX.warn, 1)
              : rgba(HEX.hudDim, 1),
        align: 'right',
        skew: 0.1,
      });

      // Hull strip — rockets must visibly chew rival integrity.
      if (!r.destroyed && ctx.combat) {
        const hpFrac = clamp01(r.hull.hp / Math.max(1, r.hull.maxHp));
        const barX = rx + 37 * s;
        const barW = plateW - 52 * s;
        const barY = y + rowH - 4.5 * s;
        const barH = 2.4 * s;
        g.fillStyle = rgba(HEX.ink, 0.85);
        g.fillRect(barX, barY, barW, barH);
        g.fillStyle = rgba(hpFrac > 0.35 ? HEX.raceLine : HEX.warn, 0.95);
        g.fillRect(barX, barY, barW * hpFrac, barH);
      }
    }
  }

  private gapText(ctx: GameContext, r: Racer, leader: Racer) {
    if (r === leader) return 'LEAD';
    const dLaps = leader.progress - r.progress;
    const metres = dLaps * ctx.track.length;
    const pace = Math.max(9, Math.abs(r.state.forwardSpeed));
    const secs = metres / pace;
    return '+' + (secs < 100 ? secs.toFixed(1) : Math.round(secs).toString());
  }

  private drawCameraChip(g: CanvasRenderingContext2D, ctx: GameContext, s: number) {
    const rig = ctx.cameraRig;
    if (!rig?.getMode || !rig.getZoom || !this.minimap) return;
    const cam =
      rig.getMode() === 'top' ? 'TOP' : rig.getMode() === 'high' ? 'HIGH' : 'CHASE';
    const race =
      ctx.raceMode === 'combat' ? 'WEAPON' : ctx.raceMode === 'timeattack' ? 'TIME' : 'CIRCUIT';
    const label = this.touchUi
      ? `${race} · ${cam}`
      : `${race} · ${cam} · Z${rig.getZoom().toFixed(1)} · C`;
    const x = this.minimap.x + this.minimap.size;
    const living = ctx.racers.filter((r) => !r.destroyed && r.state.hp > 0).length;
    const y = this.minimap.bottom + living * 28 * s + 8 * s;
    inkText(g, label, x, y, {
      font: `700 ${Math.round(10 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.waterCrest, 0.95),
      align: 'right',
      tracking: 1.5 * s,
    });
  }

  // ── Collision magnitude flash ──────────────────────────────────────────────

  private drawImpactFlash(
    g: CanvasRenderingContext2D,
    ctx: GameContext,
    w: number,
    h: number,
    s: number,
  ) {
    const imp = ctx.impactHud!;
    const life = clamp01(imp.flash / 1.2);
    const punch = 0.55 + 0.45 * life;
    const cx = w * 0.5;
    const cy = h * 0.22;
    const plateW = (210 + imp.strength * 40) * s;
    const plateH = 78 * s;
    const path = slantPath(cx - plateW * 0.5, cy - plateH * 0.5, plateW, plateH, 18 * s);

    g.save();
    g.globalAlpha = punch;
    const rocket = imp.label === 'ROCKET' || imp.label === 'MISS';
    const fill =
      imp.label === 'CRUSH' || imp.label === 'ROCKET'
        ? rgba(HEX.warn, 0.95)
        : imp.label === 'HEAVY' || imp.label === 'MISS'
          ? rgba(HEX.boostHot, 0.92)
          : rgba(HEX.hudInk, 0.9);
    inked(g, path, fill, rgba(HEX.hudPaper, 0.95), 3 * s);

    inkText(g, rocket ? 'ROCKET' : 'IMPACT', cx, cy - 18 * s, {
      font: `800 ${Math.round(11 * s)}px ${FONT_STACK}`,
      fill: rgba(
        imp.label === 'CRUSH' || imp.label === 'HEAVY' || rocket ? HEX.ink : HEX.hudDim,
        1,
      ),
      align: 'center',
      tracking: 2.2 * s,
    });

    const labelCol =
      imp.label === 'GRAZE'
        ? HEX.raceLine
        : imp.label === 'HIT'
          ? HEX.hudPaper
          : imp.label === 'HEAVY' || imp.label === 'ROCKET'
            ? HEX.ink
            : imp.label === 'MISS'
              ? HEX.foam
              : HEX.foam;
    const title = imp.label === 'ROCKET' ? 'HIT' : imp.label === 'MISS' ? 'NEAR' : imp.label;
    inkText(g, title, cx, cy + 8 * s, {
      font: `900 ${Math.round(28 * s)}px ${FONT_STACK}`,
      fill: rgba(labelCol, 1),
      align: 'center',
      skew: 0.14,
      tracking: 1.5 * s,
      ink: rgba(HEX.ink, 1),
      inkWidth: 3 * s,
    });

    // Magnitude bar
    const barW = plateW - 36 * s;
    const barH = 8 * s;
    const bx = cx - barW * 0.5;
    const by = cy + 22 * s;
    g.fillStyle = rgba(HEX.ink, 0.85);
    g.fillRect(bx, by, barW, barH);
    g.fillStyle = rgba(
      imp.strength > 0.7 ? HEX.warn : imp.strength > 0.4 ? HEX.boostHot : HEX.raceLine,
      1,
    );
    g.fillRect(bx, by, barW * clamp01(imp.strength), barH);
    g.strokeStyle = rgba(HEX.hudPaper, 0.8);
    g.lineWidth = 1.2 * s;
    g.strokeRect(bx, by, barW, barH);

    const zone = imp.zone ? imp.zone.toUpperCase() : 'MID';
    const detail = `${Math.round(imp.closingSpeed)} m/s · ${Math.round(imp.damage)} dmg · ${zone}`;
    inkText(g, detail, cx, cy + plateH * 0.5 + 14 * s, {
      font: `800 ${Math.round(11 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.hudPaper, 0.95),
      align: 'center',
      tracking: 1.4 * s,
      ink: rgba(HEX.ink, 1),
      inkWidth: 2 * s,
    });
    g.restore();
  }

  private drawPickupToast(
    g: CanvasRenderingContext2D,
    ctx: GameContext,
    w: number,
    h: number,
    s: number,
  ) {
    const toast = ctx.pickupHud!;
    const a = clamp01(toast.flash / 1.25);
    const cx = w * 0.5;
    const cy = h * 0.18;
    g.save();
    g.globalAlpha = 0.55 + 0.45 * a;
    inkText(g, toast.label, cx, cy, {
      font: `900 ${Math.round(28 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.raceLine, 1),
      align: 'center',
      skew: 0.14,
      tracking: 2.5 * s,
      ink: rgba(HEX.ink, 1),
      inkWidth: 3.5 * s,
      ghost: rgba(HEX.foam, 0.7),
      ghostDx: 3 * s,
      ghostDy: 3 * s,
    });
    g.restore();
  }

  private drawWrecked(g: CanvasRenderingContext2D, w: number, h: number, s: number) {
    const blink = 0.55 + 0.45 * Math.abs(Math.sin(this.pulse * 5));
    const cx = w * 0.5;
    const cy = h * 0.42;
    g.save();
    g.globalAlpha = blink;
    const slab = slantPath(cx - 200 * s, cy - 36 * s, 400 * s, 72 * s, 22 * s);
    inked(g, slab, rgba(HEX.ink, 0.88), rgba(HEX.warn, 0.95), 3.5 * s);
    inkText(g, 'WRECKED', cx, cy + 14 * s, {
      font: `900 ${Math.round(42 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.warn, 1),
      ink: rgba(HEX.ink, 1),
      inkWidth: 5 * s,
      align: 'center',
      skew: 0.16,
      tracking: 2 * s,
      ghost: rgba(HEX.boostHot, 0.7),
      ghostDx: 4 * s,
      ghostDy: 4 * s,
    });
    g.restore();
  }

  // ── Wrong way ──────────────────────────────────────────────────────────────

  private drawWrongWay(g: CanvasRenderingContext2D, w: number, h: number, s: number) {
    const blink = 0.45 + 0.55 * Math.abs(Math.sin(this.pulse * 6));
    const cx = w * 0.5;
    const cy = h * 0.155;
    g.save();
    g.globalAlpha = blink;
    const slab = slantPath(cx - 190 * s, cy - 28 * s, 380 * s, 56 * s, 20 * s);
    inked(g, slab, rgba(HEX.ink, 0.82), rgba(HEX.warn, 0.95), 3 * s);
    g.save();
    g.clip(slab);
    g.strokeStyle = rgba(HEX.warn, 0.5);
    g.lineWidth = 6 * s;
    for (let i = -2; i < 30; i++) {
      const bxx = cx - 190 * s + i * 14 * s;
      g.beginPath();
      g.moveTo(bxx, cy + 28 * s);
      g.lineTo(bxx + 10 * s, cy + 18 * s);
      g.stroke();
    }
    g.restore();
    inkText(g, 'WRONG WAY', cx, cy + 12 * s, {
      font: `900 ${Math.round(34 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.warn, 1),
      ink: rgba(HEX.ink, 1),
      inkWidth: 6 * s,
      align: 'center',
      skew: 0.16,
      tracking: 4 * s,
    });
    for (const dir of [-1, 1]) {
      g.strokeStyle = rgba(HEX.warn, 0.9);
      g.lineWidth = 4 * s;
      for (let i = 0; i < 2; i++) {
        const x = cx + dir * (210 + i * 18) * s;
        g.beginPath();
        g.moveTo(x + dir * 10 * s, cy - 10 * s);
        g.lineTo(x, cy);
        g.lineTo(x + dir * 10 * s, cy + 10 * s);
        g.stroke();
      }
    }
    g.restore();
  }
}
