/** Re-exports — edit values in `core/combatTune.ts`. */
export const ROCKET_DAMAGE = COMBAT.rocket.damage;
export const ROCKET_FIRE_DELAY = COMBAT.rocket.fireDelay;
export const ROCKET_HIT_RADIUS = COMBAT.rocket.hitRadius;
export const ROCKET_LIFE = COMBAT.rocket.life;

type Projectile = {
  alive: boolean;
  ownerId: number;
  targetId: number | null;
  hitChance: number;
  spoiled: boolean;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  life: number;
  spin: number;
  root: Group;
  /** Rolls with flight for fin read. */
  body: Group;
  plumeOuter: Mesh;
  plumeInner: Mesh;
};

function facetNormals(positions: Float32Array): Float32Array {
  const normals = new Float32Array(positions.length);
  for (let i = 0; i < positions.length; i += 9) {
    const ax = positions[i + 3]! - positions[i]!;
    const ay = positions[i + 4]! - positions[i + 1]!;
    const az = positions[i + 5]! - positions[i + 2]!;
    const bx = positions[i + 6]! - positions[i]!;
    const by = positions[i + 7]! - positions[i + 1]!;
    const bz = positions[i + 8]! - positions[i + 2]!;
    let nx = ay * bz - az * by;
    let ny = az * bx - ax * bz;
    let nz = ax * by - ay * bx;
    const len = Math.hypot(nx, ny, nz) || 1;
    nx /= len;
    ny /= len;
    nz /= len;
    for (let k = 0; k < 3; k++) {
      normals[i + k * 3] = nx;
      normals[i + k * 3 + 1] = ny;
      normals[i + k * 3 + 2] = nz;
    }
  }
  return normals;
}

function geoFromPos(pos: number[]): BufferGeometry {
  const arr = new Float32Array(pos);
  const g = new BufferGeometry();
  g.setAttribute('position', new BufferAttribute(arr, 3));
  g.setAttribute('normal', new BufferAttribute(facetNormals(arr), 3));
  g.computeBoundingSphere();
  return g;
}

/** Faceted tube along +Z from z0→z1. */
function tubeGeo(r0: number, r1: number, z0: number, z1: number, sides = 6): BufferGeometry {
  const pos: number[] = [];
  for (let i = 0; i < sides; i++) {
    const a0 = (i / sides) * Math.PI * 2;
    const a1 = ((i + 1) / sides) * Math.PI * 2;
    const c0 = Math.cos(a0);
    const s0 = Math.sin(a0);
    const c1 = Math.cos(a1);
    const s1 = Math.sin(a1);
    // Side quad
    pos.push(
      c0 * r0, s0 * r0, z0, c1 * r1, s1 * r1, z1, c0 * r1, s0 * r1, z1,
      c0 * r0, s0 * r0, z0, c1 * r0, s1 * r0, z0, c1 * r1, s1 * r1, z1,
    );
  }
  return geoFromPos(pos);
}

function coneGeo(r: number, zBase: number, zTip: number, sides = 6): BufferGeometry {
  const pos: number[] = [];
  for (let i = 0; i < sides; i++) {
    const a0 = (i / sides) * Math.PI * 2;
    const a1 = ((i + 1) / sides) * Math.PI * 2;
    pos.push(
      0, 0, zTip,
      Math.cos(a0) * r, Math.sin(a0) * r, zBase,
      Math.cos(a1) * r, Math.sin(a1) * r, zBase,
    );
  }
  return geoFromPos(pos);
}

/** Single swept fin in the XZ plane, later rotated around Z. */
function finGeo(): BufferGeometry {
  // Root near body → tip outboard, trailing edge aft.
  return geoFromPos([
    0.16, 0, 0.05, 0.72, 0, -0.15, 0.18, 0, -0.95,
    0.16, 0, 0.05, 0.18, 0, -0.95, 0.14, 0.05, -0.2,
    0.16, 0, 0.05, 0.14, -0.05, -0.2, 0.72, 0, -0.15,
    0.72, 0, -0.15, 0.14, -0.05, -0.2, 0.18, 0, -0.95,
    0.72, 0, -0.15, 0.18, 0, -0.95, 0.14, 0.05, -0.2,
    0.14, 0.05, -0.2, 0.18, 0, -0.95, 0.14, -0.05, -0.2,
  ]);
}

function plumeGeo(len: number, rNose: number, rTail: number): BufferGeometry {
  // Tapered flame wedge — long aft plume.
  return geoFromPos([
    rNose, 0.08, 0, -rNose, 0.08, 0, 0, 0.02, -len,
    -rNose, 0.08, 0, rNose, 0.08, 0, 0, -0.06, -len * 0.92,
    rNose, 0.08, 0, 0, 0.02, -len, 0, -0.06, -len * 0.92,
    -rNose, 0.08, 0, 0, -0.06, -len * 0.92, 0, 0.02, -len,
    rNose * 0.55, -0.02, 0, -rNose * 0.55, -0.02, 0, 0, 0.01, -len * 0.7,
    rNose * 0.35, 0.12, -0.1, -rNose * 0.35, 0.12, -0.1, 0, 0.04, -len * 0.55,
  ]);
}

function makeCel(
  name: string,
  hex: number,
  opts: {
    rim?: Color;
    outline?: number;
    flare?: number;
    ambient?: number;
    hot?: boolean;
  } = {},
) {
  const color = new Color(hex);
  const hot = !!opts.hot;
  return createCelMaterial({
    name,
    color,
    rampColors: hot
      ? [
          color.clone().multiplyScalar(0.55).lerp(new Color(HEX.boost), 0.4),
          color.clone().multiplyScalar(0.95),
          color.clone().lerp(new Color(HEX.boostHot), 0.35),
          new Color(HEX.sunCore),
        ]
      : [
          color.clone().multiplyScalar(0.55),
          color.clone().multiplyScalar(0.9),
          color.clone().multiplyScalar(1.25),
          color.clone().multiplyScalar(1.55).lerp(new Color(HEX.foam), 0.15),
        ],
    flatShading: true,
    rimColor: opts.rim ?? PAL.foam,
    rimPower: hot ? 1.35 : 1.9,
    rimStrength: hot ? 1.25 : 0.95,
    outlineWidthPx: opts.outline ?? 3.2,
    flareMask: opts.flare ?? (hot ? 1 : 0),
    ambientStrength: opts.ambient ?? (hot ? 1.35 : 0.95),
    specStrength: hot ? 0.55 : 0.28,
  });
}

type RocketMats = {
  body: ReturnType<typeof makeCel>;
  stripe: ReturnType<typeof makeCel>;
  nose: ReturnType<typeof makeCel>;
  fin: ReturnType<typeof makeCel>;
  nozzle: ReturnType<typeof makeCel>;
  plume: ReturnType<typeof makeCel>;
  plumeHot: ReturnType<typeof makeCel>;
};

type RocketGeos = {
  body: BufferGeometry;
  collar: BufferGeometry;
  nose: BufferGeometry;
  fin: BufferGeometry;
  nozzle: BufferGeometry;
  band: BufferGeometry;
  plumeOuter: BufferGeometry;
  plumeInner: BufferGeometry;
};

let _mats: RocketMats | null = null;
let _geos: RocketGeos | null = null;

function rocketMats(): RocketMats {
  if (_mats) return _mats;
  _mats = {
    body: makeCel('rocketBody', HEX.inkSoft, { outline: 3.6, ambient: 1.0 }),
    stripe: makeCel('rocketStripe', HEX.foam, {
      rim: new Color(HEX.boost),
      outline: 2.8,
      ambient: 1.2,
    }),
    nose: makeCel('rocketNose', HEX.warn, {
      hot: true,
      rim: new Color(HEX.boostHot),
      outline: 3.4,
      flare: 1,
    }),
    fin: makeCel('rocketFin', HEX.boost, {
      hot: true,
      rim: new Color(HEX.boostHot),
      outline: 2.8,
      flare: 1,
    }),
    nozzle: makeCel('rocketNozzle', HEX.ink, { outline: 2.4, ambient: 0.85 }),
    plume: makeCel('rocketPlume', HEX.boost, {
      hot: true,
      outline: 2.2,
      flare: 1,
      ambient: 1.5,
    }),
    plumeHot: makeCel('rocketPlumeHot', HEX.boostHot, {
      hot: true,
      outline: 1.6,
      flare: 1,
      ambient: 1.65,
    }),
  };
  return _mats;
}

function rocketGeos(): RocketGeos {
  if (_geos) return _geos;
  _geos = {
    body: tubeGeo(0.22, 0.2, -0.85, 0.85, 7),
    collar: tubeGeo(0.26, 0.24, 0.55, 0.82, 7),
    nose: coneGeo(0.22, 0.85, 1.55, 7),
    fin: finGeo(),
    nozzle: tubeGeo(0.28, 0.16, -1.05, -0.85, 7),
    band: tubeGeo(0.235, 0.235, 0.05, 0.22, 7),
    plumeOuter: plumeGeo(3.6, 0.28, 0.06),
    plumeInner: plumeGeo(2.4, 0.14, 0.03),
  };
  return _geos;
}

function celMesh(geo: BufferGeometry, mat: ReturnType<typeof makeCel>): Mesh {
  const m = new Mesh(geo);
  m.userData.objectId = nextObjectId();
  applyCel(m, mat);
  return m;
}

type RocketVisual = {
  root: Group;
  body: Group;
  plumeOuter: Mesh;
  plumeInner: Mesh;
};

/** Wipeout-style AG missile — faceted body, hot nose, fins, twin plume. */
function makeRocketMesh(): RocketVisual {
  const mats = rocketMats();
  const geos = rocketGeos();

  const root = new Group();
  root.rotation.order = 'YXZ';
  root.visible = false;
  root.scale.setScalar(1.35);

  const body = new Group();
  body.add(celMesh(geos.body, mats.body));
  body.add(celMesh(geos.collar, mats.stripe));
  body.add(celMesh(geos.nose, mats.nose));
  body.add(celMesh(geos.nozzle, mats.nozzle));
  body.add(celMesh(geos.band, mats.stripe));

  // Four delta fins — magenta trim so they read at chase distance.
  for (let i = 0; i < 4; i++) {
    const fin = celMesh(geos.fin, mats.fin);
    fin.rotation.z = (i / 4) * Math.PI * 2;
    fin.position.z = -0.55;
    body.add(fin);
  }

  const plumeOuter = celMesh(geos.plumeOuter, mats.plume);
  plumeOuter.position.z = -1.05;
  const plumeInner = celMesh(geos.plumeInner, mats.plumeHot);
  plumeInner.position.z = -1.0;

  root.add(plumeOuter);
  root.add(plumeInner);
  root.add(body);

  return { root, body, plumeOuter, plumeInner };
}

const _proj = new Vector3();
const _ndc = new Vector3();

export class RocketField implements Subsystem {
  readonly name = 'rockets';
  /** Before AI so panic-drift flags are ready for the drive pass. */
  readonly order = 35;

  private locks = new Map<number, LockState>();
  private breaks = new Map<number, BreakState>();
  private pool: Projectile[] = [];
  private fireCd = new Map<number, number>();
  private aiThink = new Map<number, number>();
  private root = new Group();
  private beacons = new LockBeaconField();
  private impacts = new RocketImpactField();
  private armed = false;
  private ready = false;
  /** Edge-trigger player fire so holding F doesn't dump ammo while locking. */
  private playerFireWas = false;
  /** Pressed F while locking — fire automatically once lock is ready. */
  private holdFirePending = false;

  init(ctx: GameContext) {
    this.root.name = 'rocketField';
    ctx.scene.add(this.root);
    this.beacons.init(ctx.scene);
    this.impacts.init(ctx.scene);
    ctx.combatPanicDrift = new Set();
    for (const r of ctx.racers) {
      this.locks.set(r.id, createLockState());
      this.breaks.set(r.id, createBreakState());
      this.fireCd.set(r.id, 0);
      this.aiThink.set(r.id, 0.4 + Math.random() * 0.8);
    }
    for (let i = 0; i < 24; i++) {
      const vis = makeRocketMesh();
      this.root.add(vis.root);
      this.pool.push({
        alive: false,
        ownerId: -1,
        targetId: null,
        hitChance: 0,
        spoiled: false,
        x: 0,
        y: 0,
        z: 0,
        vx: 0,
        vy: 0,
        vz: 0,
        life: 0,
        spin: 0,
        root: vis.root,
        body: vis.body,
        plumeOuter: vis.plumeOuter,
        plumeInner: vis.plumeInner,
      });
    }
    this.grantLoadout(ctx);
    this.armed = true;
    this.publishHud(ctx);
    this.ready = true;
  }

  private emptyHud(): CombatHud {
    return {
      lockName: null,
      lockStrength: 0,
      lockHitChance: 0,
      lockScreenX: null,
      lockScreenY: null,
      incoming: false,
      breakMeter: 0,
      breakFlash: 0,
      lockImmune: false,
      weaponReady: false,
      holdFirePending: false,
      ammo: 0,
      maxAmmo: ROCKET_MAX_AMMO,
      rocketCd: 0,
      rocketCdMax: ROCKET_FIRE_DELAY,
      lockHp: null,
      lockMaxHp: null,
    };
  }

  private immuneOf = (id: number) => this.breaks.get(id)?.immune ?? 0;

  private painted(id: number): boolean {
    for (const lock of this.locks.values()) {
      if (lock.targetId === id && lock.strength > 0.12) return true;
    }
    return false;
  }

  private paintedBy(id: number, shooterId: number): boolean {
    const lock = this.locks.get(shooterId);
    return !!lock && lock.targetId === id && lock.strength > 0.12;
  }

  private hasInboundRocket(id: number, fromId?: number): boolean {
    for (const p of this.pool) {
      if (!p.alive || p.spoiled || p.targetId !== id) continue;
      if (fromId != null && p.ownerId !== fromId) continue;
      return true;
    }
    return false;
  }

  private threatened(id: number): boolean {
    return this.painted(id) || this.hasInboundRocket(id);
  }

  /** Player-only threat — AI locking each other must not freeze the pack. */
  private threatenedByPlayer(id: number, playerId: number): boolean {
    return this.paintedBy(id, playerId) || this.hasInboundRocket(id, playerId);
  }

  private shatterLocksOn(ctx: GameContext, target: Racer) {
    for (const lock of this.locks.values()) {
      if (lock.targetId === target.id) {
        lock.targetId = null;
        lock.strength = 0;
      }
    }
    for (const p of this.pool) {
      if (p.alive && p.targetId === target.id) {
        p.spoiled = true;
        p.hitChance = 0;
      }
    }
    const p = target.state.position;
    this.beacons.shatterAt(p.x, p.y, p.z);
  }

  /** One rocket each at the start — pickups refill on track. */
  private grantLoadout(ctx: GameContext) {
    const R = COMBAT.rocket;
    for (const r of ctx.racers) {
      r.state.weapon = 'missile';
      r.state.weaponAmmo = R.startAmmo;
      // Stagger open fire so the pack doesn't dump on green.
      const stagger = r.isPlayer ? 0 : 0.6 + Math.random() * 2.4;
      this.fireCd.set(r.id, R.armDelay + stagger);
      const thinkSpan = R.aiThinkMax - R.aiThinkMin;
      this.aiThink.set(r.id, R.aiThinkMin + Math.random() * thinkSpan + stagger * 0.35);
    }
    this.playerFireWas = false;
  }

  private _deckPos = new Vector3();

  private deckY(ctx: GameContext, x: number, z: number, fallback: number): number {
    const tr = ctx.track;
    if (typeof tr.heightAt !== 'function') return fallback;
    const proj = tr.project(this._deckPos.set(x, 0, z));
    return tr.heightAt(proj.u) + 2.6;
  }

  /** Detonate a rocket with no damage — off-track / spent fuse. */
  private explodeRocket(ctx: GameContext, p: Projectile) {
    if (!p.alive) return;
    p.alive = false;
    p.root.visible = false;
    this.impacts.spawn(p.x, p.y, p.z, 'fuse');
    ctx.audio?.playHit();
  }

  private publishRocketHud(
    ctx: GameContext,
    shooterId: number,
    target: Racer | null,
    connected: boolean,
    damage: number,
    zone: ReturnType<typeof zoneFromImpactNormal> | null,
  ) {
    const playerShot = shooterId === ctx.player.id;
    const playerHit = !!target?.isPlayer;
    if (!playerShot && !playerHit) return;
    ctx.impactHud = {
      strength: connected ? 0.72 : 0.28,
      damage: connected ? damage : 0,
      closingSpeed: connected ? 48 : 18,
      zone,
      label: connected ? 'ROCKET' : 'MISS',
      flash: connected ? 1.25 : 0.85,
    };
    if (playerShot && connected) {
      ctx.cameraRig?.addShake(COMBAT.rocket.shakeConfirm);
    }
  }

  /** True when the rocket has left the riding surface corridor. */
  private isOffTrack(
    ctx: GameContext,
    x: number,
    y: number,
    z: number,
    margin: number = COMBAT.rocket.offTrackMargin,
  ): boolean {
    const R = COMBAT.rocket;
    const proj = ctx.track.project(this._deckPos.set(x, 0, z));
    const limit = CONFIG.race.deckHalf + margin;
    if (Math.abs(proj.lateral) > limit) return true;
    if (typeof ctx.track.heightAt === 'function') {
      const deck = ctx.track.heightAt(proj.u);
      if (y > deck + R.offDeckY || y < deck - 4) return true;
    }
    return false;
  }

  private alloc(): Projectile | null {
    for (const p of this.pool) if (!p.alive) return p;
    return null;
  }

  private fireRocket(ctx: GameContext, shooter: Racer, lock: LockState, requireLock = false) {
    if (shooter.destroyed || shooter.state.hp <= 0) return false;
    // Keep kind as missile even at 0 ammo so pads never refill rockets.
    if (shooter.state.weapon !== 'missile' || shooter.state.weaponAmmo <= 0) return false;
    const guided =
      lock.targetId != null && lock.strength >= LOCK_GUIDED_MIN;
    if (requireLock && !(lock.targetId != null && lock.strength >= LOCK_FIRE_GATE)) {
      return false;
    }
    const cd = this.fireCd.get(shooter.id) ?? 0;
    if (cd > 0) return false;
    const slot = this.alloc();
    if (!slot) return false;

    const hx = Math.sin(shooter.state.heading);
    const hz = Math.cos(shooter.state.heading);
    const rx = hz;
    const rz = -hx;
    const spd = 78 + Math.abs(shooter.state.forwardSpeed) * 0.3;
    const y = shooter.state.position.y + 0.35;
    // Slight lateral offset so salvoes from twin corners read
    const side = shooter.state.weaponAmmo % 2 === 0 ? -1 : 1;
    slot.alive = true;
    slot.ownerId = shooter.id;
    slot.targetId = guided ? lock.targetId : null;
    // Locked / guided shots connect on proximity — RNG only for dumb-fire.
    slot.hitChance = guided
      ? 1
      : COMBAT.rocket.unguidedHitChance;
    slot.spoiled = false;
    slot.x = shooter.state.position.x + hx * 5.2 + rx * side * 0.9;
    slot.y = y;
    slot.z = shooter.state.position.z + hz * 5.2 + rz * side * 0.9;
    slot.vx = hx * spd;
    slot.vy = 0;
    slot.vz = hz * spd;
    slot.life = ROCKET_LIFE;
    slot.spin = Math.random() * Math.PI * 2;
    slot.root.visible = true;
    slot.root.position.set(slot.x, slot.y, slot.z);
    slot.root.rotation.y = shooter.state.heading;
    slot.root.rotation.x = 0;
    slot.body.rotation.z = slot.spin;
    slot.plumeOuter.scale.set(1, 1, 1);
    slot.plumeInner.scale.set(1, 1, 1);

    shooter.state.weaponAmmo = Math.max(0, shooter.state.weaponAmmo - 1);
    // Stay on 'missile' at 0 — combat loadout is fixed for the race.
    this.fireCd.set(shooter.id, ROCKET_FIRE_DELAY);
    ctx.audio?.playWeapon();
    if (shooter.isPlayer) ctx.cameraRig?.addShake(COMBAT.rocket.shakeFire);
    return true;
  }

  private applyDamage(
    ctx: GameContext,
    target: Racer,
    amount: number,
    fromX: number,
    fromY: number,
    fromZ: number,
    shooterId: number,
  ) {
    if (target.destroyed) return;
    const shooter = ctx.racers.find((r) => r.id === shooterId);
    const R = COMBAT.rocket;
    // Pack fire deals real damage — slightly softened so the field doesn't wipe itself.
    const aiPack = !!shooter && !shooter.isPlayer && !target.isPlayer;
    const dmg = aiPack ? amount * R.aiVsAiDamage : amount;
    this.impacts.spawn(fromX, fromY, fromZ, 'hit');
    if (target.state.shieldTime > 0) {
      target.state.shieldTime = Math.max(0, target.state.shieldTime - 1.2);
      target.state.hitFlash = 0.45;
      target.hull.lastHitFlash = 0.55;
      ctx.audio?.playHit();
      this.publishRocketHud(ctx, shooterId, target, true, 0, 'mid');
      return;
    }
    const dx = target.state.position.x - fromX;
    const dz = target.state.position.z - fromZ;
    const len = Math.hypot(dx, dz) || 1;
    const nx = -dx / len;
    const nz = -dz / len;
    const zone = zoneFromImpactNormal(target.state.heading, nx, nz);
    const hpBefore = target.hull.hp;
    let wrecked = applyHullDamage(
      target,
      dmg,
      {
        zone,
        trauma: R.trauma,
        effects: { throttleCut: R.throttleCut },
      },
      ctx.raceTime,
    );
    // Guarantee a readable HP chunk — zone mean can undershoot the label.
    const minLoss = dmg * 0.9;
    if (!wrecked && hpBefore - target.hull.hp < minLoss) {
      const need = minLoss - (hpBefore - target.hull.hp);
      const per = need / (target.hull.maxHp * 5);
      for (const z of ['bow', 'mid', 'stern', 'port', 'starboard'] as const) {
        target.hull.zones[z] = Math.max(0, target.hull.zones[z] - per);
      }
      syncHullHp(target.hull);
    }
    target.state.hp = target.hull.hp;
    target.state.maxHp = target.hull.maxHp;
    if (!wrecked && target.hull.hp <= 0.5) {
      wreckRacer(target, ctx.raceTime);
      wrecked = true;
    }
    target.state.velocity.x += (dx / len) * R.knockback;
    target.state.velocity.z += (dz / len) * R.knockback;
    target.state.hitFlash = Math.max(target.state.hitFlash, 0.55);
    ctx.audio?.playHit();
    // ShipExplosionFx picks up `destroyed` this frame for the blast + audio.
    if (wrecked) target.root.visible = false;
    this.publishRocketHud(ctx, shooterId, target, true, dmg, zone);
    if (target.isPlayer) ctx.cameraRig?.addShake(wrecked ? R.shakeWreck : R.shakeHit);
  }

  /**
   * Personality + race context fire gate — conserve last rockets, finish
   * wounded rivals, contest place battles, still hunt the player.
   */
  private aiShouldFire(ctx: GameContext, shooter: Racer, lock: LockState): boolean {
    if (lock.targetId == null) return false;
    const target = ctx.racers.find((r) => r.id === lock.targetId);
    if (!target || target.destroyed || target.state.hp <= 0) return false;

    const R = COMBAT.rocket;
    const need =
      LOCK_FIRE_GATE +
      (shooter.personality === 'aggressive'
        ? 0.0
        : shooter.personality === 'erratic'
          ? 0.06
          : 0.1);
    if (lock.strength < need) return false;

    const ammo = shooter.state.weaponAmmo;
    const hpFrac = target.hull.hp / Math.max(1, target.hull.maxHp);
    const placeDelta = (target.place ?? 99) - (shooter.place ?? 99);
    const placeRival = Math.abs(placeDelta) <= 2;
    const ahead = target.progress > shooter.progress - 0.02;

    let chance = R.aiFireChance;
    if (shooter.personality === 'aggressive') chance += 0.22;
    else if (shooter.personality === 'clean') chance -= 0.04;
    else if (shooter.personality === 'erratic') chance += 0.12;

    if (hpFrac < 0.4) chance += 0.28;
    else if (hpFrac < 0.65) chance += 0.12;
    if (ahead && placeRival) chance += 0.22;
    if (placeDelta < 0) chance += 0.16;
    if (target.isPlayer) chance += 0.14;
    if (lock.strength > 0.55) chance += 0.16;
    if (lock.strength > 0.8) chance += 0.1;

    // When carrying a stack, save the last round for a high-value shot.
    if (ammo <= 1 && R.maxAmmo > 1) {
      const worth = hpFrac < 0.5 || placeRival || target.isPlayer || lock.strength > 0.72;
      chance *= worth ? 1.05 : 0.28;
    }

    return Math.random() < Math.min(0.94, Math.max(0.05, chance));
  }

  private clearProjectiles() {
    for (const p of this.pool) {
      p.alive = false;
      p.root.visible = false;
    }
    this.impacts.clear();
  }

  update(ctx: GameContext) {
    if (!this.ready || !ctx.combat) return;
    const dt = ctx.dt;
    const panic = ctx.combatPanicDrift ?? (ctx.combatPanicDrift = new Set());
    panic.clear();

    if (ctx.phase !== 'racing') {
      this.clearProjectiles();
      this.playerFireWas = false;
      this.holdFirePending = false;
      for (const lock of this.locks.values()) {
        lock.targetId = null;
        lock.strength = 0;
      }
      this.beacons.update([], dt, ctx.time);
      // Countdown / restart: show the rack and re-stock after RaceState clears weapons.
      if (
        ctx.phase === 'countdown' &&
        (ctx.player.state.weapon !== 'missile' || ctx.player.state.weaponAmmo <= 0 || !this.armed)
      ) {
        this.grantLoadout(ctx);
        this.armed = true;
      }
      if (ctx.phase !== 'countdown') this.armed = false;
      this.publishHud(ctx);
      return;
    }

    if (!this.armed) {
      this.grantLoadout(ctx);
      this.armed = true;
    }

    // Ensure late-join style racers still have lock/break state
    for (const r of ctx.racers) {
      if (!this.locks.has(r.id)) {
        this.locks.set(r.id, createLockState());
        this.breaks.set(r.id, createBreakState());
        this.fireCd.set(r.id, COMBAT.rocket.armDelay);
        this.aiThink.set(r.id, COMBAT.rocket.aiThinkMin);
      }
      // Carry cap — pickups may refill up to maxAmmo.
      if (r.state.weapon === 'missile') {
        r.state.weaponAmmo = Math.min(r.state.weaponAmmo, ROCKET_MAX_AMMO);
      } else if (r.state.weaponAmmo > 0) {
        r.state.weapon = 'missile';
      }
    }

    // Locks for everyone
    for (const r of ctx.racers) {
      tickLock(this.locks.get(r.id)!, r, ctx.racers, dt, this.immuneOf);
    }

    // Drift-break + AI panic. React to any painted lock / inbound rocket
    // (pack fire included); panic drive stays soft so they don't freeze.
    for (const r of ctx.racers) {
      const threatened = this.threatened(r.id);
      const inbound = this.hasInboundRocket(r.id);
      if (
        !r.isPlayer &&
        r.state.hp > 0 &&
        r.state.speedFrac > 0.28 &&
        (inbound || (threatened && Math.random() < 0.55))
      ) {
        panic.add(r.id);
      }
      const brk = this.breaks.get(r.id)!;
      const broke = tickDriftBreak(brk, r, threatened, dt);
      if (broke) {
        this.shatterLocksOn(ctx, r);
        ctx.audio?.playHit();
        if (r.isPlayer) ctx.cameraRig?.addShake(0.35);
      }
      const cd = this.fireCd.get(r.id) ?? 0;
      if (cd > 0) this.fireCd.set(r.id, Math.max(0, cd - dt));
    }

    // Player fire — F launches when ammo + cooldown allow (WaveKill rockets).
    // Lock only chooses guidance; it must never block the trigger.
    const player = ctx.player;
    const pLock = this.locks.get(player.id)!;
    const fireDown = player.controls.firePressed;
    if (player.state.weapon !== 'missile' && player.state.weaponAmmo > 0) {
      player.state.weapon = 'missile';
    }
    const ammoOk = player.state.weapon === 'missile' && player.state.weaponAmmo > 0;
    const cdOk = (this.fireCd.get(player.id) ?? 0) <= 0;
    const canShoot =
      ammoOk && cdOk && !player.destroyed && player.state.hp > 0;
    if (fireDown && canShoot && (!this.playerFireWas || this.holdFirePending)) {
      this.fireRocket(ctx, player, pLock, false);
      this.holdFirePending = false;
    } else if (fireDown && ammoOk && !cdOk) {
      // Held through cooldown — release the next shot the moment the rack arms.
      this.holdFirePending = true;
    }
    if (!fireDown) this.holdFirePending = false;
    this.playerFireWas = fireDown;

    // AI fire — pack + player, personality-aware target choice (via lock) + trigger.
    const R = COMBAT.rocket;
    for (const r of ctx.racers) {
      if (r.isPlayer || r.destroyed || r.state.hp <= 0) continue;
      if (r.state.weapon !== 'missile' || r.state.weaponAmmo <= 0) continue;
      let think = this.aiThink.get(r.id) ?? 0;
      think -= dt;
      if (think > 0) {
        this.aiThink.set(r.id, think);
        continue;
      }
      const thinkSpan = R.aiThinkMax - R.aiThinkMin;
      const pace =
        r.personality === 'aggressive' ? 0.75 : r.personality === 'erratic' ? 0.9 : 1.05;
      this.aiThink.set(r.id, (R.aiThinkMin + Math.random() * thinkSpan) * pace);
      if ((this.fireCd.get(r.id) ?? 0) > 0) continue;
      const lock = this.locks.get(r.id)!;
      if (R.aiOnlyPlayer && lock.targetId !== ctx.player.id) continue;
      if (this.aiShouldFire(ctx, r, lock)) {
        this.fireRocket(ctx, r, lock, true);
      }
    }

    this.stepProjectiles(ctx, dt);
    this.impacts.update(dt);
    this.publishBeacons(ctx, dt);
    this.publishHud(ctx);
  }

  private tryDetonate(ctx: GameContext, p: Projectile, target: Racer) {
    if (target.destroyed || target.state.hp <= 0) return false;
    p.alive = false;
    p.root.visible = false;
    // Guided lock shots always connect; dumb-fire still rolls hitChance.
    const connect =
      !p.spoiled && (p.targetId === target.id || Math.random() < p.hitChance);
    if (connect) {
      this.applyDamage(ctx, target, ROCKET_DAMAGE, p.x, p.y, p.z, p.ownerId);
    } else {
      this.impacts.spawn(p.x, target.state.position.y + 0.45, p.z, 'dud');
      ctx.audio?.playHit();
      this.publishRocketHud(ctx, p.ownerId, target, false, 0, null);
    }
    return true;
  }

  /** Closest living craft along this frame's flight segment (not owner). */
  private proximityTarget(
    ctx: GameContext,
    p: Projectile,
    prevX: number,
    prevY: number,
    prevZ: number,
  ): Racer | null {
    const r2 = ROCKET_HIT_RADIUS * ROCKET_HIT_RADIUS;
    let best: Racer | null = null;
    let bestD2 = r2;
    let cx = p.x;
    let cy = p.y;
    let cz = p.z;
    for (const r of ctx.racers) {
      if (r.id === p.ownerId || r.destroyed || r.state.hp <= 0) continue;
      const hit = this.distSqPointToSeg(
        prevX,
        prevY,
        prevZ,
        p.x,
        p.y,
        p.z,
        r.state.position.x,
        r.state.position.y + 0.35,
        r.state.position.z,
      );
      // Must be inside the fuse — lock preference only breaks ties, it must
      // not expand the radius (old d2*0.55 made locked hits fire ~35% early).
      if (hit.d2 >= r2) continue;
      const prefer = p.targetId === r.id ? hit.d2 * 0.55 : hit.d2;
      if (prefer < bestD2) {
        bestD2 = prefer;
        best = r;
        cx = hit.cx;
        cy = hit.cy;
        cz = hit.cz;
      }
    }
    if (best) {
      p.x = cx;
      p.y = cy;
      p.z = cz;
    }
    return best;
  }

  /** Squared distance from point to segment AB — catches high-speed tunnels. */
  private distSqPointToSeg(
    ax: number,
    ay: number,
    az: number,
    bx: number,
    by: number,
    bz: number,
    px: number,
    py: number,
    pz: number,
  ): { d2: number; cx: number; cy: number; cz: number } {
    const abx = bx - ax;
    const aby = by - ay;
    const abz = bz - az;
    const ab2 = abx * abx + aby * aby + abz * abz || 1e-8;
    let t = ((px - ax) * abx + (py - ay) * aby + (pz - az) * abz) / ab2;
    t = Math.max(0, Math.min(1, t));
    const cx = ax + abx * t;
    const cy = ay + aby * t;
    const cz = az + abz * t;
    const dx = px - cx;
    const dy = py - cy;
    const dz = pz - cz;
    return { d2: dx * dx + dy * dy + dz * dz, cx, cy, cz };
  }

  private stepProjectiles(ctx: GameContext, dt: number) {
    for (const p of this.pool) {
      if (!p.alive) continue;
      p.life -= dt;
      if (p.life <= 0) {
        p.alive = false;
        p.root.visible = false;
        continue;
      }

      const target =
        p.targetId != null
          ? ctx.racers.find((r) => r.id === p.targetId && !r.destroyed)
          : null;
      const guided = target != null && !p.spoiled && target.state.hp > 0;
      if (guided && target) {
        // Only a real high-slip dodge softens the shot — not AI panic brakes.
        if (isDodgeDrifting(target)) {
          p.hitChance = Math.max(0.35, p.hitChance - dt * 0.35);
        }

        // Lead the target so locks that look solid actually connect.
        const lead = COMBAT.lock.leadSec * 0.55;
        const dx = target.state.position.x + target.state.velocity.x * lead - p.x;
        const dy = target.state.position.y + 0.35 - p.y;
        const dz = target.state.position.z + target.state.velocity.z * lead - p.z;
        const len = Math.hypot(dx, dy, dz) || 1;
        const spd = Math.hypot(p.vx, p.vy, p.vz);
        const seekMul = isDodgeDrifting(target) ? 0.65 : 1;
        const seek = 5.6 * seekMul;
        const k = Math.min(1, dt * seek);
        p.vx += ((dx / len) * spd - p.vx) * k;
        p.vy += ((dy / len) * spd - p.vy) * k;
        p.vz += ((dz / len) * spd - p.vz) * k;
      } else if (p.spoiled) {
        p.vx *= 1 - dt * 0.4;
        p.vz *= 1 - dt * 0.4;
        p.vy -= 8 * dt;
      }

      const prevX = p.x;
      const prevY = p.y;
      const prevZ = p.z;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.z += p.vz * dt;

      const floor = this.deckY(ctx, p.x, p.z, p.y);
      if (p.y < floor) {
        p.y = floor;
        p.vy = Math.max(0, p.vy);
      }

      // Hit check BEFORE off-track fuse — otherwise edge shots flash and deal 0.
      const victim = this.proximityTarget(ctx, p, prevX, prevY, prevZ);
      if (victim) {
        this.tryDetonate(ctx, p, victim);
        continue;
      }

      // Guided shots get a wider apron — chase lines cut corners.
      const offMargin = guided
        ? COMBAT.rocket.offTrackMargin + 10
        : COMBAT.rocket.offTrackMargin;
      if (this.isOffTrack(ctx, p.x, p.y, p.z, offMargin)) {
        this.explodeRocket(ctx, p);
        continue;
      }

      p.root.position.set(p.x, p.y, p.z);
      p.root.rotation.y = Math.atan2(p.vx, p.vz);
      p.root.rotation.x = -Math.atan2(p.vy, Math.hypot(p.vx, p.vz));

      // Roll body + pulse exhaust so missiles read as live AG hardware.
      const rollRate = p.spoiled ? 1.2 : 9.5;
      p.spin += dt * rollRate;
      p.body.rotation.z = p.spin;
      const flicker = 0.82 + Math.sin(ctx.time * 38 + p.spin * 3) * 0.18;
      const stretch = p.spoiled ? 0.45 : 1.05 + Math.sin(ctx.time * 22 + p.ownerId) * 0.12;
      const widen = p.spoiled ? 0.55 : flicker;
      p.plumeOuter.scale.set(widen * 1.15, widen, stretch);
      p.plumeInner.scale.set(flicker * 0.85, flicker * 0.85, stretch * 0.9);
      p.plumeOuter.visible = !p.spoiled || p.life > 0.4;
      p.plumeInner.visible = p.plumeOuter.visible;
    }
  }

  private publishBeacons(ctx: GameContext, dt: number) {
    const best = new Map<number, { target: Racer; strength: number; incoming: boolean }>();
    for (const [shooterId, lock] of this.locks) {
      if (lock.targetId == null || lock.strength < 0.12) continue;
      const target = ctx.racers.find((r) => r.id === lock.targetId);
      if (!target) continue;
      const incoming = target.isPlayer;
      const prev = best.get(target.id);
      if (!prev || lock.strength > prev.strength) {
        best.set(target.id, { target, strength: lock.strength, incoming: incoming || !!prev?.incoming });
      } else if (incoming) {
        prev.incoming = true;
      }
      void shooterId;
    }
    // Also mark inbound rocket targets so player sees threat rings
    for (const p of this.pool) {
      if (!p.alive || p.spoiled || p.targetId == null) continue;
      const target = ctx.racers.find((r) => r.id === p.targetId);
      if (!target) continue;
      const prev = best.get(target.id);
      if (!prev) {
        best.set(target.id, { target, strength: 0.85, incoming: target.isPlayer });
      } else if (target.isPlayer) {
        prev.incoming = true;
        prev.strength = Math.max(prev.strength, 0.7);
      }
    }
    this.beacons.update([...best.values()], dt, ctx.time);
  }

  private publishHud(ctx: GameContext) {
    const player = ctx.player;
    const lock = this.locks.get(player.id)!;
    const brk = this.breaks.get(player.id)!;
    const raw = lock.targetId != null ? ctx.racers.find((r) => r.id === lock.targetId) : null;
    const living = raw && !raw.destroyed && raw.state.hp > 0 ? raw : null;

    let sx: number | null = null;
    let sy: number | null = null;
    if (living) {
      _proj.set(living.state.position.x, living.state.position.y + 1.4, living.state.position.z);
      _ndc.copy(_proj).project(ctx.camera);
      if (_ndc.z < 1 && Math.abs(_ndc.x) < 1.2 && Math.abs(_ndc.y) < 1.2) {
        sx = _ndc.x;
        sy = _ndc.y;
      }
    }

    // Show real guided chance as soon as the rocket would home — not only at fireGate.
    const hit =
      living && lock.strength >= LOCK_GUIDED_MIN ? hitChanceFromLock(lock.strength) : 0;
    const ammo =
      player.state.weapon === 'missile'
        ? player.state.weaponAmmo
        : Math.max(0, player.state.weaponAmmo);
    const cd = this.fireCd.get(player.id) ?? 0;
    const rackReady = ammo > 0 && cd <= 0 && !player.destroyed;
    ctx.combatHud = {
      lockName: living?.name ?? null,
      lockStrength: living ? lock.strength : 0,
      lockHitChance: hit,
      lockScreenX: sx,
      lockScreenY: sy,
      incoming: this.threatened(player.id),
      breakMeter: brk.meter,
      breakFlash: brk.breakFlash,
      lockImmune: brk.immune > 0,
      weaponReady: rackReady,
      holdFirePending: this.holdFirePending,
      ammo,
      maxAmmo: ROCKET_MAX_AMMO,
      rocketCd: cd,
      rocketCdMax: ROCKET_FIRE_DELAY,
      lockHp: living ? living.hull.hp : null,
      lockMaxHp: living ? living.hull.maxHp : null,
    };
  }

  dispose() {
    this.beacons.dispose();
    this.impacts.dispose();
    this.root.removeFromParent();
    this.ready = false;
  }
}
