/**
 * Nitro subsystem — per-racer charges, player (N) + AI ignite.
 */

import { CONFIG } from '../core/config';
import type { GameContext, Racer, Subsystem } from '../core/types';
import {
  createNitroCharge,
  resetNitroCharge,
  tickNitroCharge,
  tryActivateNitro,
} from './charge';
import { NITRO_DEFAULTS, type NitroCharge, type NitroHudSnapshot, type NitroTuning } from './types';

export type NitroSystemOpts = {
  tuning?: Partial<NitroTuning>;
  aiCharges?: boolean;
  aiCatchUpGap?: number;
};

export class NitroSystem implements Subsystem {
  readonly name = 'nitro';
  /** Before ship physics so ignite applies the same frame. */
  readonly order = 28;

  private charges = new Map<number, NitroCharge>();
  private tuning: NitroTuning;
  private aiCharges: boolean;
  private aiCatchUpGap: number;

  constructor(
    private racers: Racer[],
    opts: NitroSystemOpts = {},
  ) {
    this.tuning = { ...NITRO_DEFAULTS, ...opts.tuning };
    this.aiCharges = opts.aiCharges !== false;
    this.aiCatchUpGap = opts.aiCatchUpGap ?? 55;
    for (const r of racers) {
      if (r.isPlayer || this.aiCharges) {
        this.charges.set(r.id, createNitroCharge(this.tuning));
      }
    }
  }

  reset(): void {
    for (const n of this.charges.values()) resetNitroCharge(n, this.tuning);
    for (const r of this.racers) r.state.nitroTime = 0;
  }

  snapshot(racer: Racer): NitroHudSnapshot | null {
    const n = this.charges.get(racer.id);
    if (!n) return null;
    return {
      remaining: n.remaining,
      max: n.max,
      active: racer.state.nitroTime,
      igniteFlash: n.igniteFlash,
      readyPulse: n.readyPulse,
    };
  }

  update(ctx: GameContext): void {
    const racing = ctx.phase === 'racing';
    const L = Math.max(1, ctx.track.length);

    for (const r of this.racers) {
      const n = this.charges.get(r.id);
      if (!n) continue;
      tickNitroCharge(n, ctx.dt);

      if (!racing || r.finished || r.destroyed || r.state.hp <= 0) continue;

      if (r.isPlayer) {
        if (r.controls.nitroPressed) this.ignite(ctx, r, n);
        continue;
      }

      if (n.remaining <= 0 || r.state.nitroTime > 0) continue;
      if (Math.abs(r.state.forwardSpeed) < CONFIG.boat.topSpeed * 0.7) continue;
      const gap = (ctx.player.progress - r.progress) * L;
      const contested = gap > 20 || (gap > -45 && gap < 15 && ctx.raceTime > 10);
      if (!contested) continue;
      if (this.aiCatchUpGap > 0 && gap < -this.aiCatchUpGap) continue;
      this.ignite(ctx, r, n);
    }

    const playerSnap = this.snapshot(ctx.player);
    if (playerSnap) {
      if (!ctx.nitro) {
        ctx.nitro = { ...playerSnap };
      } else {
        ctx.nitro.remaining = playerSnap.remaining;
        ctx.nitro.max = playerSnap.max;
        ctx.nitro.active = playerSnap.active;
        ctx.nitro.igniteFlash = playerSnap.igniteFlash;
        ctx.nitro.readyPulse = playerSnap.readyPulse;
      }
    }
  }

  private ignite(ctx: GameContext, r: Racer, n: NitroCharge): void {
    if (!tryActivateNitro(n, r.state, this.tuning)) return;
    ctx.audio?.playBoost();
    if (r.isPlayer) ctx.cameraRig?.addShake(0.42);
  }
}
