/**
 * Shared Web Audio unlock — browsers require a user gesture before AudioContext
 * can leave the suspended state (Chrome autoplay policy).
 *
 * One context for the whole page; create + resume only from gesture handlers.
 */

let shared: AudioContext | null = null;
let unlockPromise: Promise<AudioContext | null> | null = null;

function getCtor(): typeof AudioContext | null {
  const w = window as Window & { webkitAudioContext?: typeof AudioContext };
  return window.AudioContext ?? w.webkitAudioContext ?? null;
}

/** True when the live context is running and can schedule sound. */
export function audioIsRunning(): boolean {
  return shared?.state === 'running';
}

export function getSharedAudioContext(): AudioContext | null {
  return shared;
}

/**
 * Call from pointerdown / keydown / click / touchend.
 * Safe to call repeatedly; returns the running context or null if still blocked.
 */
export async function unlockSharedAudio(): Promise<AudioContext | null> {
  if (shared?.state === 'running') return shared;

  if (unlockPromise) return unlockPromise;

  unlockPromise = (async () => {
    try {
      const Ctor = getCtor();
      if (!Ctor) return null;

      if (!shared) {
        shared = new Ctor();
      }

      if (shared.state === 'suspended') {
        // resume() must be kicked off in the same turn as the gesture.
        await shared.resume();
      }

      if (shared.state !== 'running') {
        // Gesture was insufficient (or tab blocked audio) — allow another try.
        return null;
      }
      return shared;
    } catch (err) {
      console.warn('[audio] unlock failed', err);
      return null;
    } finally {
      unlockPromise = null;
    }
  })();

  return unlockPromise;
}

/** Wire document-level gestures until audio is running. Returns a disposer. */
export function armAudioUnlock(onUnlocked?: () => void): () => void {
  let done = false;
  const tryUnlock = () => {
    void unlockSharedAudio().then((ctx) => {
      if (!ctx || done) return;
      if (ctx.state === 'running') {
        done = true;
        remove();
        onUnlocked?.();
      }
    });
  };

  const opts: AddEventListenerOptions = { capture: true, passive: true };
  const remove = () => {
    document.removeEventListener('pointerdown', tryUnlock, opts);
    document.removeEventListener('keydown', tryUnlock, opts);
    document.removeEventListener('touchend', tryUnlock, opts);
    document.removeEventListener('click', tryUnlock, opts);
  };

  document.addEventListener('pointerdown', tryUnlock, opts);
  document.addEventListener('keydown', tryUnlock, opts);
  document.addEventListener('touchend', tryUnlock, opts);
  document.addEventListener('click', tryUnlock, opts);

  // If a previous gesture already unlocked (hot reload / bfcache), finish now.
  if (shared?.state === 'running') {
    done = true;
    remove();
    onUnlocked?.();
  }

  return remove;
}
