/**
 * Mobile / touch overlay styles — Hotline neon pads, safe-area aware.
 * Imported once from main so Vite bundles it.
 */

const css = /* css */ `
#touch {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
}
#touch .touch-safe {
  position: absolute;
  inset: 0;
  padding:
    max(8px, env(safe-area-inset-top))
    max(10px, env(safe-area-inset-right))
    max(10px, env(safe-area-inset-bottom))
    max(10px, env(safe-area-inset-left));
  pointer-events: none;
}
#touch .touch-steer,
#touch .touch-btn,
#touch .touch-air {
  pointer-events: auto;
  -webkit-tap-highlight-color: transparent;
}
#touch .touch-steer {
  position: absolute;
  left: max(12px, env(safe-area-inset-left));
  bottom: max(16px, env(safe-area-inset-bottom));
  width: min(42vw, 168px);
  height: min(42vw, 168px);
  border-radius: 50%;
  background: rgba(22, 22, 31, 0.45);
  border: 2px solid rgba(30, 240, 240, 0.55);
  box-shadow: 0 0 0 1px rgba(255, 61, 154, 0.25) inset;
}
#touch .touch-steer-ring {
  position: absolute;
  inset: 18%;
  border-radius: 50%;
  border: 1px solid rgba(30, 240, 240, 0.28);
  pointer-events: none;
}
#touch .touch-steer-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 38%;
  height: 38%;
  border-radius: 50%;
  background: rgba(30, 240, 240, 0.85);
  border: 2px solid rgba(18, 8, 28, 0.9);
  transform: translate(-50%, -50%);
  box-shadow: 0 0 16px rgba(30, 240, 240, 0.45);
  pointer-events: none;
}
#touch .touch-label {
  position: absolute;
  left: 0; right: 0; bottom: 8%;
  text-align: center;
  font: 700 10px/1 ui-sans-serif, system-ui, sans-serif;
  letter-spacing: 0.22em;
  color: rgba(242, 251, 255, 0.7);
  pointer-events: none;
}
#touch .touch-air {
  position: absolute;
  left: max(12px, env(safe-area-inset-left));
  bottom: calc(max(16px, env(safe-area-inset-bottom)) + min(42vw, 168px) + 10px);
  display: flex;
  gap: 8px;
}
#touch .touch-air-btn {
  width: 64px;
  height: 44px;
  font-size: 11px;
}
#touch .touch-actions {
  position: absolute;
  right: max(10px, env(safe-area-inset-right));
  bottom: max(14px, env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: repeat(2, minmax(72px, 18vw));
  gap: 8px;
  pointer-events: none;
}
#touch .touch-btn {
  pointer-events: auto;
  appearance: none;
  border: 2px solid rgba(255, 61, 154, 0.7);
  background: rgba(22, 22, 31, 0.55);
  color: #f2fbff;
  font: 800 12px/1 ui-sans-serif, system-ui, sans-serif;
  letter-spacing: 0.14em;
  border-radius: 10px;
  min-height: 52px;
  padding: 0 8px;
  text-transform: uppercase;
}
#touch .touch-brake {
  grid-column: 1 / -1;
  min-height: 58px;
  border-color: rgba(255, 90, 90, 0.85);
  color: #ffc2c2;
}
#touch .touch-boost {
  border-color: rgba(255, 61, 139, 0.9);
  color: #ffb0d8;
}
#touch .touch-fire {
  border-color: rgba(255, 201, 60, 0.85);
  color: #ffe08a;
}
#touch .touch-nitro {
  border-color: rgba(77, 255, 176, 0.85);
  color: #c4ffe6;
}
#touch .touch-cam {
  border-color: rgba(106, 142, 200, 0.8);
  color: #cfe0ff;
  min-height: 44px;
}
#touch .touch-btn.is-active,
#touch .touch-steer.is-active {
  background: rgba(255, 61, 154, 0.35);
  box-shadow: 0 0 18px rgba(255, 61, 154, 0.35);
}
#touch .touch-brake.is-active {
  background: rgba(255, 90, 90, 0.4);
}
#touch .touch-fire.is-active {
  background: rgba(255, 201, 60, 0.35);
}
#touch .touch-nitro.is-active {
  background: rgba(77, 255, 176, 0.3);
}
#touch .touch-boost.is-active {
  background: rgba(255, 61, 139, 0.4);
}

@media (orientation: portrait) {
  #touch .touch-steer {
    width: min(48vw, 180px);
    height: min(48vw, 180px);
  }
  #touch .touch-actions {
    grid-template-columns: repeat(2, minmax(78px, 22vw));
  }
}

@media (max-height: 500px) {
  #touch .touch-steer {
    width: min(34vw, 130px);
    height: min(34vw, 130px);
  }
  #touch .touch-btn { min-height: 44px; font-size: 11px; }
  #touch .touch-brake { min-height: 48px; }
}
`;

let injected = false;
export function injectTouchStyles() {
  if (injected || typeof document === 'undefined') return;
  injected = true;
  const style = document.createElement('style');
  style.id = 'touch-controls-css';
  style.textContent = css;
  document.head.appendChild(style);
}
