/**
 * WaveSpace title / mode select — brand-first ink composition.
 */

import { clamp } from '../core/mathx';
import { HEX } from '../core/palette';
import { prefersTouchUi } from '../core/touchControls';
import { FONT_STACK, PLATE_SKEW, inkText, plate, rgba, slantPath } from './inkDraw';

export type ModeSelectResult = 'circuit' | 'combat' | 'timeattack';

type Card = {
  id: ModeSelectResult | null;
  title: string;
  blurb: string;
  tag: string;
  locked?: boolean;
};

const MODES: Card[] = [
  {
    id: 'combat',
    title: 'WEAPON LAPS',
    blurb: '1 rocket each — grab more on track. Lock, fire, nitro.',
    tag: 'ROCKETS',
  },
  {
    id: 'circuit',
    title: 'SPEED CIRCUIT',
    blurb: 'Three laps, full pack — rockets, nitro, and the racing line.',
    tag: 'RACE',
  },
  {
    id: 'timeattack',
    title: 'TIME ATTACK',
    blurb: 'Solo hotlaps against the clock — no AI, no weapons.',
    tag: 'SOLO',
  },
  {
    id: null,
    title: 'ZONE TOUR',
    blurb: 'Linked tracks and elimination — coming soon.',
    tag: 'SOON',
    locked: true,
  },
];

export class ModeSelect {
  private selected = 0;
  private chosen: ModeSelectResult | null = null;
  private hover = -1;
  private t0 = performance.now();
  private readonly touch = prefersTouchUi();

  constructor(private canvas: HTMLCanvasElement) {
    canvas.style.pointerEvents = 'auto';
    canvas.addEventListener('pointermove', this.onMove);
    canvas.addEventListener('pointerdown', this.onDown);
    window.addEventListener('keydown', this.onKey);
  }

  get result(): ModeSelectResult | null {
    return this.chosen;
  }

  dispose(): void {
    this.canvas.style.pointerEvents = 'none';
    this.canvas.removeEventListener('pointermove', this.onMove);
    this.canvas.removeEventListener('pointerdown', this.onDown);
    window.removeEventListener('keydown', this.onKey);
  }

  private cardRect(cssW: number, cssH: number, index: number, count: number) {
    const s = clamp(cssH / 900, this.touch ? 0.85 : 0.72, 1.35);
    const pw = Math.min(560 * s, cssW - 48 * s);
    const ph = this.touch ? (count > 3 ? 96 * s : 108 * s) : count > 3 ? 88 * s : 100 * s;
    const gap = this.touch ? 14 * s : 12 * s;
    const stack = count * ph + (count - 1) * gap;
    const px = (cssW - pw) * 0.5;
    const py = cssH * 0.42 - stack * 0.15 + index * (ph + gap);
    return { px, py, pw, ph, s };
  }

  private onMove = (ev: PointerEvent): void => {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const cssW = this.canvas.width / dpr;
    const cssH = this.canvas.height / dpr;
    this.hover = -1;
    for (let i = 0; i < MODES.length; i++) {
      const r = this.cardRect(cssW, cssH, i, MODES.length);
      if (ev.clientX >= r.px && ev.clientX <= r.px + r.pw && ev.clientY >= r.py && ev.clientY <= r.py + r.ph) {
        this.hover = i;
        this.selected = i;
      }
    }
  };

  private trySelect(index: number): void {
    const mode = MODES[index];
    if (!mode || mode.locked || mode.id == null) return;
    this.chosen = mode.id;
  }

  private onDown = (): void => {
    this.trySelect(this.hover >= 0 ? this.hover : this.selected);
  };

  private onKey = (ev: KeyboardEvent): void => {
    const n = MODES.length;
    if (ev.code === 'ArrowDown' || ev.code === 'KeyS') this.selected = (this.selected + 1) % n;
    if (ev.code === 'ArrowUp' || ev.code === 'KeyW') this.selected = (this.selected - 1 + n) % n;
    if (ev.code === 'Enter' || ev.code === 'Space') {
      ev.preventDefault();
      this.trySelect(this.selected);
    }
    if (ev.code === 'Digit1') this.trySelect(0);
    if (ev.code === 'Digit2') this.trySelect(1);
    if (ev.code === 'Digit3') this.trySelect(2);
  };

  draw(): void {
    const g = this.canvas.getContext('2d');
    if (!g) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const cssW = window.innerWidth;
    const cssH = window.innerHeight;
    if (this.canvas.width !== Math.floor(cssW * dpr) || this.canvas.height !== Math.floor(cssH * dpr)) {
      this.canvas.width = Math.floor(cssW * dpr);
      this.canvas.height = Math.floor(cssH * dpr);
      this.canvas.style.width = `${cssW}px`;
      this.canvas.style.height = `${cssH}px`;
    }

    const t = (performance.now() - this.t0) / 1000;
    g.clearRect(0, 0, this.canvas.width, this.canvas.height);
    g.save();
    g.scale(dpr, dpr);

    const sky = g.createLinearGradient(0, 0, 0, cssH);
    sky.addColorStop(0, rgba(HEX.skyZenith, 1));
    sky.addColorStop(0.4, rgba(HEX.voidMid, 1));
    sky.addColorStop(0.75, rgba(HEX.voidDeep, 1));
    sky.addColorStop(1, rgba(HEX.hudInk, 1));
    g.fillStyle = sky;
    g.fillRect(0, 0, cssW, cssH);

    g.save();
    g.globalAlpha = 0.12;
    for (let i = 0; i < 8; i++) {
      const y = cssH * 0.5 + i * 22 + Math.sin(t * 1.4 + i) * 8;
      g.strokeStyle = rgba(HEX.boost, 1);
      g.lineWidth = 2;
      g.beginPath();
      g.moveTo(0, y);
      g.lineTo(cssW, y - 40);
      g.stroke();
    }
    g.restore();

    const vig = g.createRadialGradient(cssW * 0.5, cssH * 0.3, cssH * 0.1, cssW * 0.5, cssH * 0.5, cssH * 0.85);
    vig.addColorStop(0, rgba(HEX.hudInk, 0));
    vig.addColorStop(1, rgba(HEX.hudInk, 0.55));
    g.fillStyle = vig;
    g.fillRect(0, 0, cssW, cssH);

    const s = clamp(cssH / 900, 0.72, 1.35);
    const brandY = cssH * 0.14;

    inkText(g, 'WAVESPACE', cssW * 0.5, brandY, {
      font: `900 ${Math.round(58 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.foam, 1),
      align: 'center',
      tracking: 7 * s,
      skew: 0.14,
      ink: rgba(HEX.ink, 1),
      inkWidth: 5.5 * s,
      ghost: rgba(HEX.boost, 0.85),
      ghostDx: 5 * s,
      ghostDy: 6 * s,
    });
    inkText(g, 'ANTI-GRAV RACING', cssW * 0.5, brandY + 42 * s, {
      font: `800 ${Math.round(13 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.waterCrest, 1),
      align: 'center',
      tracking: 5.5 * s,
      skew: 0.1,
    });
    inkText(g, 'Pick a circuit. Cel-shaded craft. Extreme speed.', cssW * 0.5, brandY + 66 * s, {
      font: `600 ${Math.round(12 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.hudDim, 0.95),
      align: 'center',
      tracking: 1.4 * s,
    });

    MODES.forEach((mode, i) => {
      const { px, py, pw, ph, s: sc } = this.cardRect(cssW, cssH, i, MODES.length);
      const active = i === this.selected;
      const locked = !!mode.locked;
      const accent =
        mode.id === 'combat'
          ? HEX.warn
          : mode.id === 'timeattack'
            ? HEX.hull3
            : HEX.boost;

      plate(g, slantPath(px, py, pw, ph, ph * PLATE_SKEW), sc, {
        edge: rgba(locked ? HEX.hudDim : active ? accent : HEX.hudDim, locked ? 0.3 : active ? 1 : 0.5),
        hatchRect: [px, py, pw, ph],
      });

      if (active && !locked) {
        g.fillStyle = rgba(accent, 0.9);
        g.fillRect(px, py + 6 * sc, 4 * sc, ph - 12 * sc);
      }

      inkText(g, mode.tag, px + 22 * sc, py + 26 * sc, {
        font: `800 ${Math.round(10 * sc)}px ${FONT_STACK}`,
        fill: rgba(locked ? HEX.hudDim : accent, 1),
        tracking: 3 * sc,
      });
      inkText(g, mode.title, px + 22 * sc, py + 50 * sc, {
        font: `900 ${Math.round(20 * sc)}px ${FONT_STACK}`,
        fill: rgba(HEX.hudPaper, locked ? 0.4 : 1),
        tracking: 2.6 * sc,
        skew: 0.1,
      });
      inkText(g, mode.blurb.toUpperCase(), px + 22 * sc, py + ph - 18 * sc, {
        font: `700 ${Math.round(10.5 * sc)}px ${FONT_STACK}`,
        fill: rgba(HEX.hudDim, locked ? 0.5 : 0.95),
        tracking: 1.1 * sc,
      });

      if (active && !locked) {
        inkText(g, this.touch ? 'TAP' : 'ENTER', px + pw - 20 * sc, py + ph * 0.52, {
          font: `800 ${Math.round(12 * sc)}px ${FONT_STACK}`,
          fill: rgba(HEX.boostHot, 1),
          align: 'right',
          tracking: 2.4 * sc,
        });
      }
    });

    inkText(
      g,
      this.touch
        ? 'TAP A MODE · LANDSCAPE RECOMMENDED · AUTO-THROTTLE IN RACE'
        : 'W/S OR CLICK · ENTER · 1 ROCKETS · 2 CIRCUIT · 3 TIME',
      cssW * 0.5,
      cssH - 26 * s,
      {
        font: `700 ${Math.round(10 * s)}px ${FONT_STACK}`,
        fill: rgba(HEX.hudDim, 0.85),
        align: 'center',
        tracking: 1.6 * s,
      },
    );

    g.restore();
  }
}
