/**
 * Craft-vs-craft capsule collisions — WaveKill boatPhysics model.
 * Tunables live in `core/combatTune.ts`.
 */

import { Vector3 } from 'three';
import { COMBAT } from '../core/combatTune';
import { CONFIG } from '../core/config';
import { clamp, clamp01 } from '../core/mathx';
import type { GameContext, ImpactHud, Racer, Subsystem } from '../core/types';
import {
  applyHullDamage,
  collisionHullDamage,
  collisionImpactEffects,
  collisionImpactStrength,
  impactLabel,
  tickHullEffects,
  zoneFromImpactNormal,
} from './hull';

const C = COMBAT.collision;
const _ca = new Vector3();
const _cb = new Vector3();

function colliderCentre(racer: Racer, localZ: number, out: Vector3) {
  const h = racer.state.heading;
  out.set(
    racer.state.position.x + Math.sin(h) * localZ,
    racer.state.position.y,
    racer.state.position.z + Math.cos(h) * localZ,
  );
}

export class ShipCollisions implements Subsystem {
  readonly name = 'collisions';
  /** After AI + player physics, before riders. */
  readonly order = 55;

  private hitCooldown = new Map<number, number>();

  update(ctx: GameContext) {
    const dt = ctx.dt;
    if (ctx.impactHud) {
      ctx.impactHud.flash = Math.max(0, ctx.impactHud.flash - dt);
      if (ctx.impactHud.flash <= 0) ctx.impactHud = null;
    }

    for (const r of ctx.racers) {
      const cd = this.hitCooldown.get(r.id) ?? 0;
      if (cd > 0) this.hitCooldown.set(r.id, Math.max(0, cd - dt));
      if (!r.destroyed) {
        tickHullEffects(r.hull, dt);
        r.state.hp = r.hull.hp;
        r.state.maxHp = r.hull.maxHp;
      }
    }
    if (ctx.phase === 'racing') this.resolve(ctx);
  }

  private resolve(ctx: GameContext) {
    const r = CONFIG.ship.collisionRadius;
    const racers = ctx.racers;
    const cz = C.colliderZ;

    for (let i = 0; i < racers.length; i++) {
      for (let j = i + 1; j < racers.length; j++) {
        const A = racers[i]!;
        const B = racers[j]!;
        if (A.destroyed || B.destroyed) continue;
        if (A.finished && B.finished) continue;
        const cdx = B.state.position.x - A.state.position.x;
        const cdz = B.state.position.z - A.state.position.z;
        const reach = cz + r;
        if (cdx * cdx + cdz * cdz > 4 * reach * reach) continue;

        const relSpeed = Math.hypot(
          B.state.velocity.x - A.state.velocity.x,
          B.state.velocity.z - A.state.velocity.z,
        );

        for (let a = 0; a < 2; a++) {
          for (let b = 0; b < 2; b++) {
            colliderCentre(A, a === 0 ? cz : -cz, _ca);
            colliderCentre(B, b === 0 ? cz : -cz, _cb);
            let dx = _cb.x - _ca.x;
            let dz = _cb.z - _ca.z;
            let d2 = dx * dx + dz * dz;
            const min = r * 2;
            if (d2 >= min * min) continue;

            let d = Math.sqrt(d2);
            if (d < 1e-4) {
              dx = 1;
              dz = 0;
              d = 1;
            }
            const nx = dx / d;
            const nz = dz / d;
            const overlap = min - d;

            A.state.position.x -= nx * overlap * 0.5;
            A.state.position.z -= nz * overlap * 0.5;
            B.state.position.x += nx * overlap * 0.5;
            B.state.position.z += nz * overlap * 0.5;

            const rvx = B.state.velocity.x - A.state.velocity.x;
            const rvz = B.state.velocity.z - A.state.velocity.z;
            const closing = rvx * nx + rvz * nz;
            if (closing >= 0) continue;

            const rest =
              CONFIG.ship.collisionRestitution *
              (C.restBase + clamp01(-closing / C.restClosingScale) * C.restClosingGain);
            const jimp = -(1 + rest) * closing * C.impulseMul;
            A.state.velocity.x -= nx * jimp;
            A.state.velocity.z -= nz * jimp;
            B.state.velocity.x += nx * jimp;
            B.state.velocity.z += nz * jimp;

            const zoneA = zoneFromImpactNormal(A.state.heading, nx, nz);
            const zoneB = zoneFromImpactNormal(B.state.heading, -nx, -nz);
            const fxA = collisionImpactEffects(zoneA, closing);
            const fxB = collisionImpactEffects(zoneB, closing);

            const armA = a === 0 ? 1 : -1;
            const armB = b === 0 ? 1 : -1;
            const spin = clamp(
              -closing * CONFIG.ship.collisionSpin * (C.spinRelBase + relSpeed / C.spinRelDiv),
              0,
              C.spinMax,
            );
            const sideA = Math.sign(nx * Math.cos(A.state.heading) - nz * Math.sin(A.state.heading));
            const sideB = Math.sign(nx * Math.cos(B.state.heading) - nz * Math.sin(B.state.heading));
            A.state.heading += spin * armA * sideA * -0.016 * fxA.spinMul;
            B.state.heading += spin * armB * sideB * 0.016 * fxB.spinMul;

            if (-closing < C.grazeClosing) continue;

            const baseDmg = collisionHullDamage(closing, relSpeed);
            // Pack traffic: AI↔AI bumps shove but barely damage (no train wrecks).
            const aiPack = !A.isPlayer && !B.isPlayer;
            const mul = aiPack ? 0.12 : 1;
            this.hitCraft(ctx, A, zoneA, baseDmg * fxA.damageMul * mul, fxA, -closing, relSpeed);
            this.hitCraft(ctx, B, zoneB, baseDmg * fxB.damageMul * mul, fxB, -closing, relSpeed);
          }
        }
      }
    }
  }

  private hitCraft(
    ctx: GameContext,
    racer: Racer,
    zone: ReturnType<typeof zoneFromImpactNormal>,
    damage: number,
    fx: ReturnType<typeof collisionImpactEffects>,
    closingMag: number,
    relSpeed: number,
  ) {
    const cd = this.hitCooldown.get(racer.id) ?? 0;
    if (cd > 0 || racer.destroyed) return;
    this.hitCooldown.set(racer.id, C.hitCooldown);

    const strength = collisionImpactStrength(-closingMag);
    const relBoost = clamp01(relSpeed / 50);
    const strengthHud = clamp01(strength * 0.75 + relBoost * 0.35);

    if (racer.state.shieldTime > 0) {
      racer.state.shieldTime = Math.max(0, racer.state.shieldTime - 0.8);
      racer.state.hitFlash = Math.max(racer.state.hitFlash, 0.2);
      racer.hull.lastHitZone = zone;
      racer.hull.lastHitFlash = 0.35;
      ctx.audio?.playHit();
      if (racer.isPlayer) {
        ctx.cameraRig?.addShake(C.shakeShieldBase + strengthHud * C.shakeShieldPerStrength);
        this.publishImpact(ctx, strengthHud, 0, closingMag, zone);
      }
      return;
    }

    const applied = Math.max(0, damage);
    const wrecked = applyHullDamage(
      racer,
      applied,
      {
        zone,
        trauma: strengthHud * C.traumaPerStrength,
        effects: {
          steerBias: fx.steerBias,
          throttleCut: fx.throttleCut,
          boostBleed: fx.boostBleed,
        },
      },
      ctx.raceTime,
    );

    ctx.audio?.playHit();
    if (racer.isPlayer) {
      ctx.cameraRig?.addShake(C.shakeBase + strengthHud * C.shakePerStrength);
      this.publishImpact(ctx, strengthHud, applied, closingMag, zone);
      if (wrecked) ctx.cameraRig?.addShake(C.shakeWreck);
    }
  }

  private publishImpact(
    ctx: GameContext,
    strength: number,
    damage: number,
    closingMag: number,
    zone: ImpactHud['zone'],
  ) {
    const s = clamp01(strength);
    const prev = ctx.impactHud;
    if (prev && prev.flash > 0 && prev.strength > s) return;
    ctx.impactHud = {
      strength: s,
      damage,
      closingSpeed: closingMag,
      zone,
      label: impactLabel(s),
      flash: C.impactFlashBase + s * C.impactFlashPerStrength,
    };
  }
}
