/**
 * Tiny top-down craft damage schematic — WaveKill boatMap port for WaveSpace.
 */

import { clamp01 } from '../core/mathx';
import { HEX } from '../core/palette';
import type { HullZoneId } from '../core/types';
import { FONT_STACK, inkText, inked, rgba } from './inkDraw';

export type ShipMapInput = {
  zones: Record<HullZoneId, number>;
  lastHitZone: HullZoneId | null;
  lastHitFlash: number;
  hp: number;
  maxHp: number;
  time: number;
};

function zoneColor(integrity: number, flash: boolean, time: number): string {
  const t = clamp01(integrity);
  if (flash) {
    const blink = 0.55 + 0.45 * Math.sin(time * 28);
    return rgba(HEX.warn, blink);
  }
  if (t > 0.65) return rgba(HEX.raceLine, 0.55 + t * 0.45);
  if (t > 0.35) return rgba(HEX.boostHot, 0.7 + t * 0.3);
  return rgba(HEX.warn, 0.75 + (1 - t) * 0.25);
}

/**
 * Draw a compact plan-view craft with coloured damage zones.
 * Origin top-left of the plate area (x, y). Returns drawn size.
 */
export function drawShipDamageMap(
  g: CanvasRenderingContext2D,
  x: number,
  y: number,
  s: number,
  inp: ShipMapInput,
): { w: number; h: number } {
  const w = 78 * s;
  const h = 118 * s;
  const cx = x + w * 0.5;
  const flashZone = inp.lastHitFlash > 0.05 ? inp.lastHitZone : null;

  g.fillStyle = rgba(HEX.hudInk, 0.92);
  g.strokeStyle = rgba(HEX.hudPaper, 0.55);
  g.lineWidth = 1.4 * s;
  g.beginPath();
  g.rect(x, y, w, h);
  g.fill();
  g.stroke();

  inkText(g, 'HULL', cx, y + 12 * s, {
    font: `800 ${Math.round(8 * s)}px ${FONT_STACK}`,
    fill: rgba(HEX.hudDim, 1),
    align: 'center',
    tracking: 1.6 * s,
  });

  // Wipeout arrowhead silhouette (top = nose)
  const top = y + 20 * s;
  const bot = y + h - 22 * s;
  const midY = (top + bot) * 0.5;
  const halfW = 24 * s;
  const nose = top;
  const chin = top + 34 * s;
  const wing = bot - 18 * s;
  const tail = bot;

  const hit = (z: HullZoneId) => flashZone === z;

  // Nose / bow
  const bow = new Path2D();
  bow.moveTo(cx, nose);
  bow.lineTo(cx - halfW * 0.55, chin);
  bow.lineTo(cx + halfW * 0.55, chin);
  bow.closePath();
  inked(g, bow, zoneColor(inp.zones.bow, hit('bow'), inp.time), rgba(HEX.ink, 1), 1.5 * s);

  // Mid — port / centre / starboard
  const port = new Path2D();
  port.moveTo(cx - halfW * 0.55, chin);
  port.lineTo(cx - halfW, wing);
  port.lineTo(cx - halfW * 0.28, wing);
  port.lineTo(cx - halfW * 0.28, chin);
  port.closePath();
  inked(g, port, zoneColor(inp.zones.port, hit('port'), inp.time), rgba(HEX.ink, 1), 1.3 * s);

  const centre = new Path2D();
  centre.moveTo(cx - halfW * 0.28, chin);
  centre.lineTo(cx + halfW * 0.28, chin);
  centre.lineTo(cx + halfW * 0.28, wing);
  centre.lineTo(cx - halfW * 0.28, wing);
  centre.closePath();
  inked(g, centre, zoneColor(inp.zones.mid, hit('mid'), inp.time), rgba(HEX.ink, 1), 1.3 * s);

  const star = new Path2D();
  star.moveTo(cx + halfW * 0.28, chin);
  star.lineTo(cx + halfW * 0.28, wing);
  star.lineTo(cx + halfW, wing);
  star.lineTo(cx + halfW * 0.55, chin);
  star.closePath();
  inked(g, star, zoneColor(inp.zones.starboard, hit('starboard'), inp.time), rgba(HEX.ink, 1), 1.3 * s);

  // Stern / engines
  const stern = new Path2D();
  stern.moveTo(cx - halfW, wing);
  stern.lineTo(cx + halfW, wing);
  stern.lineTo(cx + halfW * 0.45, tail);
  stern.lineTo(cx - halfW * 0.45, tail);
  stern.closePath();
  inked(g, stern, zoneColor(inp.zones.stern, hit('stern'), inp.time), rgba(HEX.ink, 1), 1.5 * s);

  // Outer silhouette
  const hull = new Path2D();
  hull.moveTo(cx, nose);
  hull.lineTo(cx - halfW * 0.55, chin);
  hull.lineTo(cx - halfW, wing);
  hull.lineTo(cx - halfW * 0.45, tail);
  hull.lineTo(cx + halfW * 0.45, tail);
  hull.lineTo(cx + halfW, wing);
  hull.lineTo(cx + halfW * 0.55, chin);
  hull.closePath();
  g.strokeStyle = rgba(HEX.hudPaper, 0.85);
  g.lineWidth = 1.6 * s;
  g.stroke(hull);

  g.strokeStyle = rgba(HEX.hudDim, 0.45);
  g.lineWidth = 1 * s;
  g.beginPath();
  g.moveTo(cx, nose + 4 * s);
  g.lineTo(cx, tail - 3 * s);
  g.stroke();

  inkText(g, `${Math.round(inp.hp)}`, cx, y + h - 8 * s, {
    font: `800 ${Math.round(11 * s)}px ${FONT_STACK}`,
    fill: rgba(inp.hp / inp.maxHp > 0.35 ? HEX.hudPaper : HEX.warn, 1),
    align: 'center',
    tracking: 1.2 * s,
  });

  if (flashZone) {
    inkText(g, flashZone.toUpperCase(), cx, midY, {
      font: `800 ${Math.round(9 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.foam, 0.95),
      align: 'center',
      tracking: 1.4 * s,
      ink: rgba(HEX.ink, 1),
      inkWidth: 2 * s,
    });
  }

  return { w, h };
}
