/**
 * Rocket pickups along the circuit — one missile per collect.
 * Tunables in `core/combatTune.ts`.
 */

import {
  BufferAttribute,
  BufferGeometry,
  Color,
  Group,
  Mesh,
  Vector3,
} from 'three';
import { COMBAT } from '../core/combatTune';
import { HEX, PAL } from '../core/palette';
import { Rng } from '../core/rng';
import type { GameContext, Subsystem, TrackAPI } from '../core/types';
import { applyCel, createCelMaterial, nextObjectId } from '../render/celMaterial';
import { ROCKET_MAX_AMMO } from './lockOn';

type Slot = {
  alive: boolean;
  x: number;
  y: number;
  z: number;
  respawnAt: number;
  root: Group;
};

function boxGeo(sx: number, sy: number, sz: number): BufferGeometry {
  const hx = sx * 0.5;
  const hy = sy * 0.5;
  const hz = sz * 0.5;
  const faces: [number, number, number][][] = [
    [[-hx, hy, -hz], [hx, hy, -hz], [hx, hy, hz], [-hx, hy, hz]],
    [[-hx, -hy, hz], [hx, -hy, hz], [hx, -hy, -hz], [-hx, -hy, -hz]],
    [[-hx, -hy, hz], [-hx, hy, hz], [hx, hy, hz], [hx, -hy, hz]],
    [[hx, -hy, -hz], [hx, hy, -hz], [-hx, hy, -hz], [-hx, -hy, -hz]],
    [[hx, -hy, -hz], [hx, -hy, hz], [hx, hy, hz], [hx, hy, -hz]],
    [[-hx, -hy, hz], [-hx, -hy, -hz], [-hx, hy, -hz], [-hx, hy, hz]],
  ];
  const positions: number[] = [];
  const normals: number[] = [];
  for (const f of faces) {
    const ax = f[1]![0] - f[0]![0];
    const ay = f[1]![1] - f[0]![1];
    const az = f[1]![2] - f[0]![2];
    const bx = f[2]![0] - f[0]![0];
    const by = f[2]![1] - f[0]![1];
    const bz = f[2]![2] - f[0]![2];
    let nx = ay * bz - az * by;
    let ny = az * bx - ax * bz;
    let nz = ax * by - ay * bx;
    const len = Math.hypot(nx, ny, nz) || 1;
    nx /= len;
    ny /= len;
    nz /= len;
    for (const tri of [
      [f[0], f[1], f[2]],
      [f[0], f[2], f[3]],
    ]) {
      for (const v of tri) {
        positions.push(v![0], v![1], v![2]);
        normals.push(nx, ny, nz);
      }
    }
  }
  const g = new BufferGeometry();
  g.setAttribute('position', new BufferAttribute(new Float32Array(positions), 3));
  g.setAttribute('normal', new BufferAttribute(new Float32Array(normals), 3));
  g.computeBoundingSphere();
  return g;
}

/** Simple missile silhouette on top of the crate. */
function missileGeo(): BufferGeometry {
  const pos: number[] = [];
  const nrm: number[] = [];
  const pushTri = (
    a: [number, number, number],
    b: [number, number, number],
    c: [number, number, number],
  ) => {
    const ux = b[0] - a[0],
      uy = b[1] - a[1],
      uz = b[2] - a[2];
    const vx = c[0] - a[0],
      vy = c[1] - a[1],
      vz = c[2] - a[2];
    let nx = uy * vz - uz * vy;
    let ny = uz * vx - ux * vz;
    let nz = ux * vy - uy * vx;
    const len = Math.hypot(nx, ny, nz) || 1;
    nx /= len;
    ny /= len;
    nz /= len;
    for (const p of [a, b, c]) {
      pos.push(p[0], p[1], p[2]);
      nrm.push(nx, ny, nz);
    }
  };
  // Body along +Z
  const y = 0.48;
  pushTri([-0.08, y, -0.28], [0.08, y, -0.28], [0.08, y + 0.1, 0.2]);
  pushTri([-0.08, y, -0.28], [0.08, y + 0.1, 0.2], [-0.08, y + 0.1, 0.2]);
  pushTri([-0.08, y + 0.1, 0.2], [0.08, y + 0.1, 0.2], [0, y + 0.05, 0.42]);
  const g = new BufferGeometry();
  g.setAttribute('position', new BufferAttribute(new Float32Array(pos), 3));
  g.setAttribute('normal', new BufferAttribute(new Float32Array(nrm), 3));
  g.computeBoundingSphere();
  return g;
}

function makeRocketMesh(): Group {
  const bodyColor = new Color(HEX.warn);
  const bodyMat = createCelMaterial({
    name: 'rocketBox',
    color: bodyColor,
    rampColors: [
      bodyColor.clone().multiplyScalar(0.55),
      bodyColor.clone().multiplyScalar(0.9),
      bodyColor.clone().lerp(new Color(HEX.boostHot), 0.35),
      new Color(HEX.foam),
    ],
    flatShading: true,
    rimColor: PAL.boostHot,
    rimPower: 1.5,
    rimStrength: 1.05,
    outlineWidthPx: 3.2,
  });
  const body = new Mesh(boxGeo(0.85, 0.65, 0.85));
  body.userData.objectId = nextObjectId();
  applyCel(body, bodyMat);

  const tipColor = new Color(HEX.boost);
  const tipMat = createCelMaterial({
    name: 'rocketBoxTip',
    color: tipColor,
    rampColors: [
      tipColor.clone().multiplyScalar(0.7),
      tipColor,
      new Color(HEX.boostHot),
      new Color(HEX.foam),
    ],
    flatShading: true,
    outlineWidthPx: 2.2,
    rimStrength: 0.7,
    ambientStrength: 1.2,
  });
  const tip = new Mesh(missileGeo());
  tip.userData.objectId = nextObjectId();
  applyCel(tip, tipMat);

  const root = new Group();
  root.add(body);
  root.add(tip);
  root.scale.setScalar(1.3);
  root.visible = false;
  return root;
}

const _tpScratch = {
  position: new Vector3(),
  tangent: new Vector3(0, 0, 1),
  curvature: 0,
  u: 0,
};

/** Give one rocket if under carry cap. Returns true if ammo was granted. */
export function tryCollectRocket(racer: { state: { weapon: string; weaponAmmo: number } }): boolean {
  const max = ROCKET_MAX_AMMO;
  if (racer.state.weaponAmmo >= max) return false;
  racer.state.weapon = 'missile';
  racer.state.weaponAmmo = Math.min(max, racer.state.weaponAmmo + 1);
  return true;
}

export class RocketBoxField implements Subsystem {
  readonly name = 'rocketBoxes';
  readonly order = 43;

  private slots: Slot[] = [];
  private rng = new Rng(0x524f_434b);
  private ready = false;
  private track: TrackAPI | null = null;

  init(ctx: GameContext) {
    this.track = ctx.track;
    const n = COMBAT.rocketBox.count;
    for (let i = 0; i < n; i++) {
      const root = makeRocketMesh();
      ctx.scene.add(root);
      this.slots.push({
        alive: false,
        x: 0,
        y: 0,
        z: 0,
        respawnAt: 0,
        root,
      });
    }
    this.reseedAll(ctx);
    this.ready = true;
  }

  reset(ctx?: GameContext) {
    const salt = Math.floor((ctx?.time ?? Math.random()) * 1000) >>> 0;
    this.rng = new Rng(0x524f434b ^ salt);
    if (ctx) this.reseedAll(ctx);
    else {
      for (const s of this.slots) {
        s.alive = true;
        s.respawnAt = 0;
        s.root.visible = true;
      }
    }
  }

  private reseedAll(ctx: GameContext) {
    for (const s of this.slots) this.placeRandom(s, ctx);
  }

  private placeRandom(slot: Slot, ctx: GameContext) {
    const H = COMBAT.rocketBox;
    const track = this.track ?? ctx.track;
    const clear = H.startClearance;
    const usable = Math.max(40, track.length - clear * 2);
    const d = clear + this.rng.next() * usable;
    const pt = track.sampleDistance(d, _tpScratch);
    const tx = pt.tangent.x;
    const tz = pt.tangent.z;
    const lateral = this.rng.sym(H.lateralMax);
    const rx = tz;
    const rz = -tx;
    slot.x = pt.position.x + rx * lateral;
    slot.z = pt.position.z + rz * lateral;
    const deckY =
      typeof track.heightAt === 'function' ? track.heightAt(pt.u) : pt.position.y;
    slot.y = deckY + H.hoverY;
    slot.alive = true;
    slot.respawnAt = 0;
    slot.root.visible = true;
    slot.root.position.set(slot.x, slot.y, slot.z);
  }

  update(ctx: GameContext) {
    if (!this.ready || !ctx.combat) return;
    const H = COMBAT.rocketBox;
    const t = ctx.time;
    const r2 = H.radius * H.radius;

    if (ctx.phase !== 'racing' && ctx.phase !== 'countdown') {
      for (const s of this.slots) {
        s.root.visible = s.alive;
        if (s.alive) {
          const bob = Math.sin(t * 3.1 + s.x * 0.07) * H.bobAmp;
          s.root.position.y = s.y + bob;
          s.root.rotation.y = t * 1.35;
        }
      }
      return;
    }

    for (const s of this.slots) {
      if (!s.alive) {
        if (t >= s.respawnAt) this.placeRandom(s, ctx);
        else continue;
      }

      const bob = Math.sin(t * 3.1 + s.x * 0.07) * H.bobAmp;
      s.root.position.set(s.x, s.y + bob, s.z);
      s.root.rotation.y = t * 1.35;
      s.root.rotation.z = Math.sin(t * 2.2 + s.z * 0.04) * 0.12;

      const candidates = ctx.racers
        .filter((r) => {
          if (r.destroyed || r.finished) return false;
          if (r.state.weaponAmmo >= ROCKET_MAX_AMMO) return false;
          const dx = r.state.position.x - s.x;
          const dz = r.state.position.z - s.z;
          return dx * dx + dz * dz <= r2;
        })
        .sort((a, b) => Number(b.isPlayer) - Number(a.isPlayer));

      const r = candidates[0];
      if (r && tryCollectRocket(r)) {
        s.alive = false;
        s.root.visible = false;
        s.respawnAt = t + H.respawnSec;
        ctx.audio?.playWeapon();
        if (r.isPlayer) {
          ctx.pickupHud = { label: 'ROCKET', flash: 1.2 };
          ctx.cameraRig?.addShake(0.1);
        }
      }
    }
  }

  dispose() {
    for (const s of this.slots) {
      s.root.removeFromParent();
      s.alive = false;
    }
    this.slots.length = 0;
    this.ready = false;
  }
}
